quests[64065] = { id = 64065, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Local Reagents", description = "Korthia is an odd place. The wildlife here is different, likely due to years of exposure to the Vault and everything it contains.\n\nAre you ready to try some experiments? We'll need a good stock of reagents first.\n\nNear the Seeker's Quorum, you should be able to find shardhides, gromits, and razorwings. Watch out for their needles!", progress = "Feel like taste testing my newest experiment? It probably won't kill you.", completion = "This needle is so long and perfect! Well done apprentice. I can't wait to get started on our new tests!", objectives = "Collect 8 Shardhide Talons, 6 Gromit Feet, and 1 Razorwing Spines for Plague Deviser Marileth in Korthia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64070] = { id = 64070, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Staying Scrappy", description = "Our army always need more weapons, armor, and troops. Always.\n\nWe're getting reinforcements, but I can't keep everyone properly armed at this rate. Especially without a full forge and assistants.\n\nWe'll have to make do with the next best thing. I need you to go get me any kind of scrap metal from the Mawsworn you can find. I'll figure out how to turn it into usable weapons.", progress = "One day, I'll fight a campaign where we are properly supplied and equipped. It'll be the easiest war I'll ever fight.", completion = "Well, it's not the finest materials, but it will do.", objectives = "Collect 12 Mawsworn scrap metal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64080] = { id = 64080, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Down to Earth", description = "I can hear the wings of the Mawsworn in the sky up above, taunting us. \n\nBut a bird in the hand can be crushed. \n\nTake my spear and prove your aim. Pull a few down and smite them. \n\nBe sure to use the spear. Do not traipse among them so that they will chase you back down to the ground. That's not the point.\n\nI want to see you drag them out of the sky.", completion = "It is so satisfying to see those flying Mawsworn get their wings clipped.\n\nWell done, my friend.", objectives = "Use Korayn's Javelin to spear 4 Mawsworn Harbingers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64083] = { id = 64083, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sinfall Tactician", description = "Sinfall is gaining more respect than Denathrius could have ever hoped to earn! It is all thanks to your efforts, {name}.\n\nZo'sorg has once again requested your presence in Oribos. Go at once.\n\nThe favor of Cartel Zo is not something we want to squander. A broker clan's trust is not one effortlessly gained.\n\nPerhaps they have more rewards to bestow upon you.", completion = "I see your skills in combat have improved even further. I trust you have made good use of our previous offer? \n\nZo'dash is now instructed to offer the full suite of his services to you. I look forward to seeing their impact on your performance.", objectives = "Meet with Zo'sorg in the Enclave in Oribos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64084] = { id = 64084, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Necrolord Tactician", description = "You have brought great honor to the Necrolords. Such honor attracts the attention of others yet again.\n\nZo'sorg has once again requested your presence in Oribos. Go at once.\n\nThe favor of Cartel Zo is not something we want to squander. A broker clan's trust is not one effortlessly gained.\n\nPerhaps they have more rewards to bestow upon you.", completion = "I see your skills in combat have improved even further. I trust you have made good use of our previous offer? \n\nZo'dash is now instructed to offer the full suite of his services to you. I look forward to seeing their impact on your performance.", objectives = "Meet with Zo'sorg in the Enclave in Oribos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64085] = { id = 64085, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Night Fae Tactician", description = "Your bravery has allowed Ardenweald to grow once again. It has also once again drawn the attention of brokers.\n\nZo'sorg has once again requested your presence in Oribos. Go at once.\n\nThe favor of Cartel Zo is not something we want to squander. A broker clan's trust is not one effortlessly gained.\n\nPerhaps they have more rewards to bestow upon you.", completion = "I see your skills in combat have improved even further. I trust you have made good use of our previous offer? \n\nZo'dash is now instructed to offer the full suite of his services to you. I look forward to seeing their impact on your performance.", objectives = "Meet with Zo'sorg in the Enclave in Oribos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64086] = { id = 64086, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kyrian Tactician", description = "Look around you, {name}. Elysian Hold stands as a testament to the progress we have made thanks to you.\n\nZo'sorg has once again requested your presence in Oribos. Go at once.\n\nThe favor of Cartel Zo is not something we want to squander. A broker clan's trust is not one effortlessly gained.\n\nPerhaps they have more rewards to bestow upon you.", completion = "I see your skills in combat have improved even further. I trust you have made good use of our previous offer? \n\nZo'dash is now instructed to offer the full suite of his services to you. I look forward to seeing their impact on your performance.", objectives = "Meet with Zo'sorg in the Enclave in Oribos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64089] = { id = 64089, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teas and Tinctures", description = "How delightful! What a lovely little spot of nature.\n\nHave you tried the local brews? Perhaps a nice herbal tea? No? Well, let's try it together! Search about this place and bring back any herbs that look... interesting.\n\nA good spot of tea, and then we shall get to work. I'll wait here.", progress = "Tubbins! Grubbins! What are the two of you up to? Not bothering the Night Fae again are you?", completion = "Oh my! I've never even seen most of these herbs. Hum, this black one looks a bit dangerous. This green one seems promising. Well done {name}!", objectives = "Collect 12 potential tea materials.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64090] = { id = 64090, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Big Squeeze", description = "So our missin' blue got 'imself dragged off to the big squeeze. Fortunately I am wise to the prise.\n\nWe'll soft foot it in like we work there, find your moose, avoid eye contact with the fangs, and chisel out of 'ere like we're masons. Follow?", progress = "Well, this is exciting!", completion = "It sounds like Huln might not have much time left!", objectives = "Head to where Cudgelface thinks Huln was taken, and blend in.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64091] = { id = 64091, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mal'appropriated", description = "<The dreadlord catches your eye, wishing to speak. You glance at your companions. Moonberry urges you forward with a mischievous grin. You step as close as you dare.>\n\nFree me from this prison, mortal, and you will have my favor. I am aligned with powers greater than these pathetic puppets or their masters. They have no concept of the true forces at work. \n\nAll I need are the sigils of binding which hold me. The rest I can... take care of.\n\nFree me, and you will be granted untold power.", progress = "Hmmm.", completion = "If he got nicked, I know where they took 'im.", objectives = "Collect the Sigils of Binding", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64092] = { id = 64092, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunting Huln", description = "Huln is somewhere in the area, but the Stonewright isn't letting anyone in to her territory because of the recent, ah, troubles with Dreadlords. The guards won't let anyone in, and they're kicking out anyone who doesn't look like they belong.\n\nLuckily for Huln, Cudgelface and I came up with a foolproof plan!\n\nWe just need to look like we belong and then we can ask around and find Huln. Easy!", completion = "I'm busy with this piece of dreadlord filth. Find something useful to do before the Stonewright gets angry. You don't want to see her angry.", objectives = "Don a disguise then search Dominance Keep for Huln Highmountain while avoiding the guards.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64101] = { id = 64101, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Proper Procedures", completion = "There's so much anima here. This will be very useful in helping the attendants rebuild. Thank you.", objectives = "Collect 5 Lost Anima Vessels.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64104] = { id = 64104, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Think of the Critters", description = "The wildlife of Korthia have been through so much. Some of them can't seem to find enough to eat.\n\nI've saved some extra food that we can share with them. \n\nBut I'm worried that they might be too shy to trust us, and I don't blame them! \n\nHere. Take these treats and see if you can get close enough to them to feed them properly. Even small creatures are so important.", completion = "You were able to feed some of them? Wonderful!\n\nI'll start saving up more food for next time. I hope that one day we can help this place heal, too.", objectives = "Approach and feed Hungry Gromits in Korthia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64106] = { id = 64106, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Unified Effort", description = "You have made strong allies within your covenant as well as the others within the Shadowlands. This bond is why they have decided to loan aid to our cause.\n\nThey are ready to fight alongside us as we begin our advance into the Maw.\n\nEach covenant will strike at the Jailer from a different area. Help them scour this treacherous land for any who serve Zovaal so that we may put an end to his growing influence.", completion = "Do not relent, {name}. This is only the first of many battles to come.", objectives = "Aid the covenants in assaulting the Jailer's forces in the Maw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64129] = { id = 64129, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Charge of the Wild Hunt", description = "Ever since I joined the Wild Hunt I've learned so much about how to fight and how to defend the realms. \n\nI admit I'm still learning. But I am so glad to be learning alongside you, and my runestag friend, Aldermeigh.\n\nAldermeigh is being trained to charge into battle with the bravery of a vorkai, but he needs practice. Will you take him out for a ride, and mow down all the Mawsworn you can?", completion = "You and Aldermeigh make a great team! Thank you for taking him out and dispatching so many Mawsworn.\n\nOne day, I too will ride with the Wild Hunt, and we will right many wrongs.", objectives = "Mount Aldermeigh and slay Mawsworn in Korthia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64131] = { id = 64131, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[64138] = { id = 64138, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[64159] = { id = 64159, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Repatriate Rare Supplies", description = "The rebels have stolen supplies from surrounding camps.\n\nYou have proven yourself adept at correcting such situations. I trust you can aid us in resolving this situation.", objectives = "Recover supplies from the makeshift camps across the river.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64162] = { id = 64162, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritual Rival", description = "Yet another rival Kahn has risen out of the rebel tribes.\n\nI'd take care of then myself, but I'm busy overseeing things here. \n\nI trust you can teach them the error of their ways?", objectives = "Find and defeat the Rebel Kahn in the makeshift camps across the river.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64163] = { id = 64163, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Revenge Against Renegades", description = "Rebel clans have laid claims to some of our camps across the river.\n\nSuch rebellious rabble need dealing with.\n\nI trust that you are capable of teaching these rebels a lesson on my behalf?\n\nThe camps are an untidy mess as well, so just ignore the chaos for now. We can resolve that later once order is restored.", objectives = "Find and defeat Rebel Centaur Warriors in the makeshift camps across the river.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64166] = { id = 64166, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Random Memory Access", description = "When the Jailer snared Korthia and dragged it toward the Maw, he destroyed so much in this place. Not only mountains and buildings, but the people, too.\n\nThose people had lives, hopes, memories.\n\nI have to think that they can't all be gone, and we might be able to save something of them that lingers.\n\nHere, take some of my power. See if you can collect those memories. Bring them to me, and I'll keep them safe. \n\nNo one should be forgotten.", completion = "Thank you, {name}. I'll make sure these memories are taken care of. \n\nI wonder what it would have been like, being here as one of them...", objectives = "Collect Korthian Memories using the Ephemeral Wings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64167] = { id = 64167, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pets Detective", description = "I'm so glad you're here, {name}!\n\nI've been expecting a delivery of pet supplies and some new pets.  But my distribution manager, Zantini has not reported in. I suspect foul play.\n\nThere's been some shady people eyeballing my store for a while now. But I haven't been able to leave the store and track them down. You can.\n\nTake my pet cat, Fiona, and find these well hidden spies.", progress = "What have you learned, {name}?", completion = "So there is a group of violet, pet fanatics in the Eye of Azshara?", objectives = "Investigate the city of Dalaran with Breanni's special spy catching cat, Fiona.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64168] = { id = 64168, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Spore of Marasmius", objectives = "Take us home?", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64169] = { id = 64169, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Ella", objectives = "Ella has been reunited with her grub. You should probably give them a good home.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64170] = { id = 64170, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: ELGU - 007", objectives = "Power restored. Awaiting Input.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64171] = { id = 64171, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Kiaranyka", objectives = "Thank you Maw Walker. I know my Aspirant will be grateful. I would like to aid you in your task, if you would allow me.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64172] = { id = 64172, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Ryuja Shockfist", objectives = "That was quite the workout. Let's do it again sometime.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64173] = { id = 64173, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Kinessa the Absorbent", objectives = "I think we should leave now. We shall speak of this to no-one.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64174] = { id = 64174, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Steadyhands", objectives = "Well now I need to put this platter to use. 'Ow about I serves you?", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64175] = { id = 64175, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Lassik Spinebender", objectives = "Do your colleagues require aid? I am sure I can be of some use.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64184] = { id = 64184, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missing Friend" }
