quests[64188] = { id = 64188, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ryuja's Supplies" }
quests[64189] = { id = 64189, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kinessa's Support" }
quests[64190] = { id = 64190, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steadyhands' Platter" }
quests[64191] = { id = 64191, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lassik's Gear" }
quests[64194] = { id = 64194, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "War Prototype", description = "As Forgelite Prime, I always work to make something better!\n\nBut largest centurions, they are much too large to bring to Korthia. This, I fix. Here is Atleos, field colossus prototype. Vanguard of the Kyrian! \n\nIt needs testing. More testing. Must be perfect against a powerful opponent.\n\nGo, take Atleos and defeat a great Maw beast! Press all the buttons!", progress = "You have work still, yes?", completion = "Ha! Perfect victory. Atleos returns, and you do too.", objectives = "Use the Atleos prototype in the Windswept Aerie to defeat Kraxis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64196] = { id = 64196, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pet Up", description = "It sounds like some group of pet poachers are up to no good in the Eye of Azshara. My supply manager's flight path takes him right over that area!\n\nZantini and his pets, Strigfellow and Speedy IV, were bringing back a rare murloc pet, along with some other pets and supplies.\n\n{name}, please find Zantini and his pets. Help them out. Then we can try to recover the pets and the supplies.", completion = "Thanks for the rescue, pal. Stringfellowe, Speedy IV and me appreciate it.", objectives = "Find and help Zantini and his pets along the coast of the Eye of Azshara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64202] = { id = 64202, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gotta Hand It To Ya", description = "Your power Maw Walker... it rivals even mine before Zovaal separated my body.\n\nThis is but a small part of my whole, but more than enough...\n\nAllow me to aid you in your efforts against Zovaal.  In doing so my vengeance will be fulfilled.", completion = "<The five rings glow and morph their power coalescing into a small ring that would perfectly fit your finger.>\n\n<Nilganihmaht's voice booms in your head> \n\nLet us embark from this place and bring down Zovaal together.", objectives = "Accept Nilganihmaht's help.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64203] = { id = 64203, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Coast is Clear", description = "I was on the last leg of a supply run when we were shot down! They took the pets, but the supplies are scattered over this stretch of beach.\n\nI don't know what they're planning, but I know we gotta get our supplies. You an' me, we ain't subtle.... But Speedy IV... He won't cause all them pirates to go into hiding. He can get the supplies while Stringfellowe surveils the area from the air.\n\nSpeedy's fond of you, so chat him up and let's try to recover the smoldering supplies before they all burn up.", progress = "Supplies are always in need.", completion = "We got our pet supplies back. Now we gotta get our pets.", objectives = "Gather pet supplies along the shores of Eye of Azshara with Speedy IV.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64210] = { id = 64210, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Box of Many Things", description = "Ah, Maw Walker, of course. Soon I shall be undone, claimed by this place forever. But you continue to walk its halls, unbroken!\n\nIt was my great aspiration to prevail with the help of this box. Sadly, I overestimated my own capabilities.\n\nI trust I am not overestimating yours. Take the box. Prove yourself worthy of it.", progress = "Ah, you return.", completion = "Ah... a curious device. Anchoring it in this place will prove useful.", objectives = "Bring the Box of Many Things to the Runecarver.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64211] = { id = 64211, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Doorway in the Dark", description = "I fear our efforts to stop Zovaal have been thwarted, mortal.\n\nA doorway has been opened to a forbidden realm... and the Banished One has reclaimed a power taken from him long ago.\n\nI sense your allies returning from the Sanctum of Domination. I must know every detail of what transpired.", completion = "<Jaina appears sad, but resolute.>\n\nWe still have hope.", objectives = "Speak to Jaina and witness the end of the battle in Torghast.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64212] = { id = 64212, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Doorway in the Dark", description = "I fear our efforts to stop Zovaal have been thwarted, mortal.\n\nA doorway has been opened to a forbidden realm... and the Banished One has reclaimed a power taken from him long ago.\n\nI sense your allies returning from the Sanctum of Domination. I must know every detail of what transpired.", completion = "<Thrall's brow is furrowed.>\n\nWe can't let the Jailer win.", objectives = "Speak to Thrall and witness the end of the battle in Torghast.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64213] = { id = 64213, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Symbol of Hope", description = "Before Anduin followed the Jailer through the gateway, he dropped something.\n\nI don't think this was part of the Jailer's plan. It must be a sign that Anduin's soul is still his own!\n\n<Jaina opens her hand to show you a golden compass.>\n\nThis was very personal to Anduin. I feel his presence upon it.\n\nWe need to know why he left it for us.", progress = "If Anduin was able to leave this for us to find, then some part of him must still be free from the Jailer's domination...", completion = "<Tears fall from Jaina's eyes.>\n\nWe cannot lose him, {name}. No matter what it takes.", objectives = "Assist Jaina in examining Anduin's compass.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64214] = { id = 64214, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Symbol of Hope", description = "Before Anduin followed the Jailer through the gateway, he dropped something.\n\nI'm not sure what it was, but Jaina picked it up. Perhaps this is a sign that Anduin is still fighting back against the Jailer!\n\nWe need to find out what this object was, and why the young king left it for us.", progress = "Why did Anduin leave this for us to find?", completion = "Anduin Wrynn does not deserve such a fate.\n\nWe must fight to save him, {name}!", objectives = "Assist in examining Anduin's compass.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64215] = { id = 64215, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paw Patrol", description = "While Speedy IV was collecting supplies, Stringfellowe was scouting the rest of the Eye of Azshara.\n\nTurns out there is a whole mess of pirates to the west.  That must be where the pets are at.\n\nHead over there and rescue the pets.", progress = "Have you found them, {name}?", completion = "Nice work freeing the pets, {name}. \n\nBut still no sign of Gurgl.", objectives = "Obtain keys from the Violetsail pirates along the west coast of the Eye of Azshara. Then set the captured pets free.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64216] = { id = 64216, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tower Knowledge", description = "The woven power of this box can only be unlocked by feeding it pride and memory. In its weave are incantations I have seen used in the other realms to siphon or condition a soul. This... abomination... has used these tools of redemption and honor to create a lock.\n\nAs you challenge the floors of Torghast, your skill, speed, and efficiency will all contribute to Tower Knowledge which this box can feed upon. \n\nFeed it to retrieve the powers within.", progress = "<The Box of Many Things thrums with power.>", completion = "<The box hungers, reaching into your memories of Torghast for past deeds to feed upon.>", objectives = "Place the Box of Many Things in Torghast.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64218] = { id = 64218, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Danger Near and Far", description = "We have done all we can about the Jailer for now, my friend. \n\nOther matters require our attention. Like the devourer rifts I recently saw opening to the east! \n\nIf we do not stop them, those beasts will wreak havoc on this place.\n\nWill you help me take care of them, {name}?", completion = "Someone inside needs our help!", objectives = "Investigate the Genesis Fields.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64219] = { id = 64219, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Mysterious Voice", description = "So much destruction. The devourers are insatiable. \n\nI hope the creature we heard is not badly hurt.\n\nThis door is not going to open normally. Perhaps we can force our way through together!\n\nWhatever is on the other side needs our help.", progress = "We must help whoever is trapped inside!", completion = "We were too late... but we must not give up hope.", objectives = "Enter the Cradle of Nascence.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64223] = { id = 64223, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Core of the Matter", description = "She has fallen, but appears to still be alive. There must be something we can do to help her.\n\nLet us see if the Enlightened know anything. I will find some way to transport her and meet you back in Haven.", progress = "Let us hope we are not too late.", completion = "That was unhelpful...", objectives = "Speak with Elder Kreth in Haven.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64224] = { id = 64224, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeking the Unknown", description = "If the Elders will not assist us, we must find someone who will. \n\nThat other Enlightened, Firim... he was much more interested in the automa. \n\nHe said he was estranged from his kin. Someone in Haven must know something about him. \n\nLook around the camp for clues about Firim's whereabouts. I will try again to convince the Elders to talk.", progress = "Have you found anything?", completion = "The elders refuse to say anything about Firim.\n\nI hope you were able to learn something.", objectives = "Search Haven for information about Firim.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64225] = { id = 64225, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finding Firim", description = "You found something? What luck! May I see the letter?\n\nSo, an Enlightened named Xevveth heard that Firim was last seen west of the Forge of the Afterlives, and went to go seek him out. \n\nWe should begin our search there.", completion = "Those assassins are after more than just my life. They wish to steal my research! I cannot let them have it.", objectives = "Find Firim.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64226] = { id = 64226, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Security Measures", description = "It seems the hidden traps I placed around the grotto are not as effective as I would like, considering your presence in my home. \n\nHowever, they are still useful in preventing the majority of unwanted attention. \n\nSince you so kindly brought assassins to me, I cannot reset the traps myself. \n\nSo you will need to do it for me. I will stay here to guard both myself and my precious research. Use this Sensory Synchronizer I placed nearby to show you which traps need to be reset.", completion = "Good. That should shield us from notice for a while.", objectives = "Use the Sensory Synchronizer, then reset 10 Triggered Traps near Exile's Hollow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64227] = { id = 64227, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unseen Agents", description = "Ever since you opened the way from Oribos, certain cartels have taken the opportunity to come after me and my work in a rather... lethal fashion. They know how important my research is to everything. \n\nMore assassins are sure to follow, what with you blazing a clear path right to me! \n\nI cannot get them all. You need to fix this and help protect my secrets. \n\nTake care of them for me.", completion = "I suppose you have proven to be useful. Thank you.", objectives = "Kill assassins near Exile's Hollow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64228] = { id = 64228, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Now You May Speak", description = "You truly brought me an oracle! Intact even!\n\nI have never known these divine beings to speak to anyone but automa. There is so much we could learn from her about Zereth Mortis.\n\nYou must tell me everything!", progress = "Let me hear what happened...", completion = "Astounding!", objectives = "Talk to Firim about the oracle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64230] = { id = 64230, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cyphers of the First Ones", description = "The way is not quite clear, but the first steps have been made.\n\nIt seems the divine construct has taken more of a liking to you than to me. \n\nNow that it has given you the beginnings of understanding, see what else it wishes to show you.\n\nThe results should be enlightening.", progress = "You have been blessed.", completion = "Can't you feel the knowledge you've gained coursing through you?!\n\nTo think it is you who will unlock the secrets of Zereth Mortis...\n\nI will be watching you very closely.", objectives = "Investigate the Cypher Console.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64237] = { id = 64237, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gurgl and the Bandit", description = "We've got all the pets back except Gurgl. {name}, we need to get that pet back for Breanni.\n\nStringfellowe saw a nook where we think the leader of these pet poachers is hiding out. \n\nLet's get 'em!", completion = "You're back, {name}! And you've brought back our supplies, pets and Gurgl!!\n\nGurgl doesn't seem to want to leave your side.\n\nHe's been through enough hard times and I am not going to break this one's little heart.\n\nTake care of my friend, {name}.\n\nTake care of my friend, Gurgl.", objectives = "Find and battle the leader of the pet poachers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64240] = { id = 64240, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flight of the Kyrian", description = "We've engaged in a heavy battle at the entrance to the Vault of Secrets! Our forces could use some reinforcement.\n\nPlease, guide my fellow Ascended to give support to our fighters there. \n\nThe fighters on the ground can handle the clean-up, but they need shields and healing.\n\nGood luck!", progress = "Have you helped our forces at the Vault of Secrets?", completion = "You don't always need to strike with force from the skies! Sometimes just a little extra help from healing is the best tactic.\n\nThank you, my friend.", objectives = "Assist covenant forces from the air at the Vault of Secrets.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64255] = { id = 64255, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Party Time", progress = "Oh neat that looks like Temel's hat!", completion = "<Your butler has a cheshire grin as he takes the party hat.>" }
quests[64266] = { id = 64266, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supplies from The Archivists' Codex", description = "I have no words to express the warmth that fills me knowing your dedication has ensured Korthia's history remain intact.\n\nPlease. Allow me to share my gratitude.", completion = "I have no words to express the warmth that fills me knowing your dedication has ensured Korthia's history remain intact.\n\nPlease. Allow me to share my gratitude.", objectives = "Speak with Archivist Roh-Suir in the Reliquary of Remembrance in Korthia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64267] = { id = 64267, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mysterious Gifts from Ve'nari", description = "I'm impressed by your sheer tenacity to survive while remaining somewhat useful, Maw Walker. You remind me of myself when I was much younger and naive. \n\nTake this and continue your work... somewhere less conspicuous.", completion = "I'm impressed by your sheer tenacity to survive while remaining somewhat useful, Maw Walker. You remind me of myself when I was much younger and naive. \n\nTake this and continue your work... somewhere less conspicuous.", objectives = "Speak with Ve'nari at Ve'nari's Refuge in the Maw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64271] = { id = 64271, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A More Civilized Way", completion = "Your form still needs work. Thank you, for taking time out of our unending campaign to duel. We must remember, even in times of great struggle, to do things that bring us joy.", objectives = "Meet Nadjia near the road leading into Korthia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64273] = { id = 64273, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Containing the Helsworn" }
quests[64274] = { id = 64274, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[64282] = { id = 64282, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Full of Surprises", description = "You continue to surprise me Maw Walker, your presence here is most unexpected!\n\nSince we are both here, I believe we should work together.\n\nThe Jailer has a vault full of valuables, somewhere in this rift.  Locate it for me, or bring it here to be opened and we'll share the wealth together!", progress = "Have you found the vault?", completion = "This is quite a profitable partnership. I am certain Cartel Ve will be most unhappy with our success.", objectives = "Locate Zovaal's Vault.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64286] = { id = 64286, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragon of Death's Advance", description = "The call to action has been answered, yet again. Your efforts shall not go unnoticed.\n\nLet us see if we cannot find a fitting reward for your efforts.", completion = "The first of many interactions, I hope.\n\nPlease. Accept this as a token of our appreciation.", objectives = "Speak with Duchess Mynx at Keeper's Respite in Korthia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64287] = { id = 64287, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragon of The Archivists' Codex", description = "You have gone to great lengths to restore that which we cherish most dearly, Maw Walker.\n\nMeet me in my chamber when you are ready. We have one final matter to discuss.", completion = "The value of that which we hold in our possession endures while they remain in our presence, but knowledge and memories exist in a space that cannot be misplaced or stolen, only forgotten.\nMay the journey and memories of our time together remain with you always.", objectives = "Speak with Archivist Roh-Suir at the Reliquary of Remembrance in Korthia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64288] = { id = 64288, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragon of Ve'nari", description = "Come, Maw Walker. Meet me at my refuge.\n\nWe have one final matter to discuss.\n\n...and do make sure you are not followed.", completion = "Our arrangement has benefited me quite nicely.\n\n<Ve'nari looks around, admiring how her hard work has paid off.>\n\nNow, before I plunge this sack of discarded waste into the darkness, perhaps there is something here you may find of use.\n\nAnd do not let this go to your head, Maw Walker. Think of this as an investment in your future dedication to my cause.", objectives = "Speak with Ve'nari at Ve'nari's Refuge in The Maw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64289] = { id = 64289, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Picking Up the Pieces", description = "Much was lost when Korthia was pulled into the Maw.\n\nPriceless relics were torn asunder. I have seen creatures carrying the remnants of these items. \n\nThey must be recovered.\n\nConfront the Jailer's forces and search what remains of Korthia for these fragments of our once glorious vault.", completion = "These will do nicely. There is much I can do to improve them.", objectives = "Recover 50 Relic Fragments from rare creatures and treasures throughout Korthia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64290] = { id = 64290, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Collecting Research", description = "You have done well to collect these fragments. They will go a long way to restoring our archives. \n\nI can use what you have found to gather more research about what was lost within Korthia. \n\nAfterwards, it will be up to you to find more fragments and relics within Korthia to boost our archives.", progress = "We thank you for your aid so far, Maw Walker.", completion = "This should do nicely. The reliquary will improve with more research.", objectives = "Speak with Archivist Roh-Suir to turn in any Korthian Relics for Cataloged Research.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64292] = { id = 64292, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maelie, The Wanderer", description = "I can't thank you enough for finding Maelie! You know, I think she's just a little bit more than I can handle.\n\nWould you mind watching over her? I think she's really taken a liking to you!", completion = "Take care of Maelie, Maw Walker.", objectives = "Accept responsibility for Maelie.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64304] = { id = 64304, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "New Opportunities Await", description = "Going somewhere in a hurry? Ah, yes. You, Maw Walker--you would not happen to be venturing to explore the new, mysterious mass within the Maw, would you?\n\nI do wonder what secrets it holds.\n\nPerhaps there is something we can do to help one another.\n\nIf this is of interest to you then let us continue our discussion. If not, move along. I will find someone else to do the job.", completion = "Excellent work, indeed.\n\nA reward for your efforts, and to our continued shared interests.", objectives = "Slay 20 players in Korthia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64306] = { id = 64306, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quest Completion Criteria" }
quests[64314] = { id = 64314, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Covenants Renewed", description = "Our efforts were focused on preventing the Jailer from shattering the barrier around the Maw and invading the rest of the Shadowlands.\n\nInstead, he expanded the Maw itself to envelop Oribos and claim the Aribiter's sigil.\n\nI do not fully understand what we witnessed atop Torghast. But the Primus certainly does.\n\nIt is time to enact his contingency plan. The covenants will arrive with their sigils shortly. \n\nInform the Primus that we are ready to begin.", completion = "Excellent, mortal. You have done your part.\n\nNow my work begins.", objectives = "Speak to the Primus, then claim the Sigils from each covenant.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64322] = { id = 64322, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Night Fae Veteran", description = "Ardenweald is safer than it has been in quite some time, thanks to you.\n\nYour accomplishments have not gone unnoticed, even beyond the borders of Ardenweald.\n\nTales of your victories have echoed through the halls of Oribos. Zo'sorg, the Master of Conflict, has requested a meeting with you in the Enclave.\n\nThey have a keen interest in the art of war. I suggest you don't keep them waiting.", completion = "Ah, {name}. I have heard many stories of your prowess on the battlefield. \n\nI have interest in keeping great combatants like yourself well equipped. Zo'dash is authorized to further upgrade your armor and weapons.", objectives = "Meet with Zo'sorg in the Enclave in Oribos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64323] = { id = 64323, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kyrian Veteran", description = "Bastion is healing thanks to you, {name}. The path is clear.\n\nYour accomplishments have not gone unnoticed, even beyond the borders of Bastion.\n\nTales of your victories have echoed through the halls of Oribos. Zo'sorg, the Master of Conflict, has requested a meeting with you in the Enclave.\n\nThey have a keen interest in the art of war. I suggest you don't keep them waiting.", completion = "Ah, {name}. I have heard many stories of your prowess on the battlefield. \n\nI have interest in keeping great combatants like yourself well equipped. Zo'dash is authorized to further upgrade your armor and weapons.", objectives = "Meet with Zo'sorg in the Enclave in Oribos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64324] = { id = 64324, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Necrolord Veteran", description = "The might of the Necrolords grows thanks to you, {name}.\n\nYour accomplishments have not gone unnoticed, even beyond the borders of Maldraxxus.\n\nTales of your victories have echoed through the halls of Oribos. Zo'sorg, the Master of Conflict, has requested a meeting with you in the Enclave.\n\nThey have a keen interest in the art of war. I suggest you don't keep them waiting.", completion = "Ah, {name}. I have heard many stories of your prowess on the battlefield. \n\nI have interest in keeping great combatants like yourself well equipped. Zo'dash is authorized to further upgrade your armor and weapons.", objectives = "Meet with Zo'sorg in the Enclave in Oribos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64325] = { id = 64325, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sinfall Veteran", description = "Sinfall's influence grows thanks to your triumphs, {name}!\n\nYour accomplishments have not gone unnoticed, even beyond the borders of Revendreth.\n\nTales of your victories have echoed through the halls of Oribos. Zo'sorg, the Master of Conflict, has requested a meeting with you in the Enclave.\n\nThey have a keen interest in the art of war. I suggest you don't keep them waiting.", completion = "Ah, {name}. I have heard many stories of your prowess on the battlefield. \n\nI have interest in keeping great combatants like yourself well equipped. Zo'dash is authorized to further upgrade your armor and weapons.", objectives = "Meet with Zo'sorg in the Enclave in Oribos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64340] = { id = 64340, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bewitching", progress = "Does everyone on your world wear these pointy hats?!", completion = "<Your butler tries out a terribly awkward cackle as he takes the hat, then coughs remembering his decorum.>" }
quests[64368] = { id = 64368, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relic Efficiency", objectives = "Your work in restoring the reliquary has been invaluable.\n\nI've uncovered new methods to find relics. Hopefully they will help you.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64376] = { id = 64376, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hidden Quest" }
quests[64430] = { id = 64430, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spill the Tea", description = "It seems Tubbins and Gubbins have gone off somewhere.\n\nI do worry about the two of them. Be a dear and check on them. One never knows what shenanigans they might be up to.\n\nI last saw them speaking with one of the faeries from Ardenweald. They were discussing the fine art of tea making.", completion = "Ah, you've all returned safely. Wonderful!", objectives = "Find Tubbins and Gubbins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64432] = { id = 64432, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strength to Weakness", completion = "I told you it would be fine. How did the test go? I wish I could have seen the looks on their faces when their fancy armor was suddenly the reason they were being destroyed.", objectives = "Empower the lightning rod, then kill mawsworn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64437] = { id = 64437, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inform the Primus", description = "{name}, return to Korthia and tell the Primus that the Winter Queen's sigil has been restored.", completion = "Ah, good. With the Queen's Sigil restored, we're that much closer to being able to stop Zovaal. Thank you for this information.", objectives = "Return to the Primus in Korthia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64438] = { id = 64438, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Empowering Equipment", description = "The research you find can unlock many possibilities.\n\nOne such avenue is improving some equipment that you may find within Korthia.\n\nSpeak with my assistant nearby. He can use our research to restore this equipment to its former power.", progress = "I will do what I can to aid you, Maw Walker.", completion = "This is the least we can do to help you in your efforts, Maw Walker.", objectives = "Speak with Assistant Scholar Kah-Vez to upgrade one piece of equipment from Korthia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64441] = { id = 64441, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Loose Thread", description = "<A book appears to have been recently knocked off the table from the nearby Venthyr encampment.\n\nThe Venthyr would likely appreciate you returning it to them before one of the gromits uses it for nesting material.>", completion = "<It appears you and Mal'ganis are not done with one another. When you finally confront the Jailer, you are certain the dreadlord will be there as well.>", objectives = "Pick up the book to return it.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64458] = { id = 64458, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurer: Sulanoom", objectives = "Your devotion to Ardenweald is unquestionable, {name}.\n\nSulanoom was especially impressed by your unshakable spirit, so much so that they wish to join our fight here.\n\nLet's make good use of their services!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64459] = { id = 64459, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurer: Elwyn", objectives = "The forest blesses us, {name}. Your interest in the wellbeing of Ardenweald has not gone unnoticed.\n\nThe venerable Elwyn has agreed to join our fight.\n\nTogether we shall protect the realm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64460] = { id = 64460, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurer: Yanlar", objectives = "{name}, you have fought many valiant battles for Ardenweald.\n\nYanlar has joined you for many fights across the Shadowlands and has been continually impressed with your valor. \n\nI am delighted to say that they have asked to permanently fight with you.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64461] = { id = 64461, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurer: Hermestes", objectives = "Your faith in Bastion is inspiring, {name}.\n\nHermestes has seen your unflagging dedication to our cause.\n\nIt has inspired them to join us in a different capacity at the Hold, so that they may contribute further to the greater needs of the Shadowlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64462] = { id = 64462, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurer: Cromas the Mystic", objectives = "Greetings, my mortal friend! I have good tidings.\n\nCromas the Mystic has watched your progress with Kyrian with great interest for quite some time.\n\nNow he wishes to join you and lend his courage and skills to our cause.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64463] = { id = 64463, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurer: Auric Spiritguide", objectives = "It seems we have another recruit, {name}.\n\nI am honored to say that the Auric Spiritguide has decided to lend their wisdom and skills to our cause.\n\nShe will make a wonderful ally!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64464] = { id = 64464, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurer: Lyra Hailstorm", objectives = "We've got an exciting development today, {name}!\n\nLyra Hailstorm wants join our ranks here at the Seat! Her expertise will be a welcome addition.\n\nNow go fight together for the good of Maldraxxus!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64465] = { id = 64465, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurer: Enceladus", objectives = "Your dedication is inspiring, {name}.\n\nYou have made quite an impression on Enceladus. Fixing your weapons has shown him that you are a true warrior.\n\nThe purpose is clear, fight for Maldraxxus!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64466] = { id = 64466, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurer: Deathfang", objectives = "We've got exciting news today, {name}.\n\nBaroness Draka has given us the distinct honor of conscripting Deathfang into our service.\n\nMaldraxxus shall be victorious with help from this ferocious beast!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64467] = { id = 64467, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurer: Chachi the Artiste", objectives = "Exquisite news, {name}.\n\nChachi the Artiste has decided to lend his exquisite taste in service to Revendreth.\n\nBe sure to make good use of his skills.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64468] = { id = 64468, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurer: Madame Iza", objectives = "Madame Iza has decided to enter the fray in service of Revendreth.\n\nIsn't that exciting, {name}?\n\nHer remarks aren't the only thing that is cutting, so do not underestimate her in a fight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64469] = { id = 64469, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurer: Lucia", objectives = "Lucia wishes to bring her wealth of skills to our cause {name}.\n\nShe's been restless to punish those who have turned on Revendreth.\n\nUse her well.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64506] = { id = 64506, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Must Be Found", description = "There is much detailed in the codex. Items that are forever lost, and some that still exist.\n\nSome powerful relics may remain, hidden somewhere within Korthia. \n\nBrowse the reliquary. You will find echoes of artifacts that are still whole here in Korthia.\n\nCommit them to memory. You must find them and return them to me.", progress = "Have you seen the missing relics?", completion = "These are just some of the relics that are missing.\n\nYou have the power to recover them, wherever they are within Korthia.", objectives = "Examine what relics are missing within the Reliquary of Remembrance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64509] = { id = 64509, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stylish Cover", progress = "Is that ta' same type of head topper Hips from the Sinstone Swingers wears?", completion = "Is that actually his spare hat? I can't believe it, I think I see some sweat on the band... thank you!" }
quests[64511] = { id = 64511, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missing Relics", description = "Thanks to your aid, I have been able to recover more research regarding the lost relics from the vault.\n\nI have gone over the codex and believe there are more relics within Korthia that can still be recovered.\n\nThese were sealed within chests that I believe have been scattered in Korthia during the initial attack.\n\nI have set up the missing relics in here. Commit them to memory. They must be recovered.", progress = "Have you seen the missing relics?", completion = "Please, do what you can to find these relics. We must not let this knowledge fall to ruin.", objectives = "Examine the missing relics within the Reliquary of Remembrance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64513] = { id = 64513, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ve'rayn's Head", description = "<Ve'rayn has been hunting Ve'nari for some time. Ve'nari would be very interested in seeing proof that she has been dealt with permanently.>", completion = "Is that what I think it is...?", objectives = "Deliver Ve'rayn's Head to Ve'nari in Ve'nari's Refuge.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64517] = { id = 64517, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Byron Test - Item Gained" }
quests[64518] = { id = 64518, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Byron Test - Obtain Any Item" }
quests[64519] = { id = 64519, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost Vaults", description = "I have finished my research on more relics that may still exist in Korthia. I believe they are still within our smaller vaults.\n\nWith your help, I can recreate devices that are capable of repairing the entrances to these vaults.\n\nTake note of the echoes of relics that are still missing. Please review them so you know what to look for.", progress = "Have you seen the missing relics?", completion = "Thank you for your continued aid. The reliquary will be restored, thanks to your diligent work.", objectives = "Examine the missing relics within the Reliquary of Remembrance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64521] = { id = 64521, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helsworn Battle Plans", description = "<These battle plans detail possible movements into Korthia, and include detailed reports of the defensive capabilities of the Death's Advance in the region.\n\nDuchess Mynx in Keeper's Respite would be able to spread this information rapidly to those who need it.>", completion = "<Duchess Mynx's eyes widen as she browses the documents you brought her.>\n\nI will disseminate these immediately. Thank you!", objectives = "Deliver Helsworn Battle Plans to Duchess Mynx in Keeper's Respite.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64522] = { id = 64522, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stolen Korthian Supplies", description = "<These supplies are marked with the seal of the Death's Advance, stolen from the Rift without being noticed.\n\nDuchess Mynx in Keeper's Respite would be very grateful to have this returned.>", completion = "<Duchess Mynx looks at you incredulously.>\n\nYou found these WHERE?!\n\nWell, how am I supposed to stop thieves I cannot even see? Cowardly shades!", objectives = "Deliver Stolen Korthian Supplies to Duchess Mynx in Keeper's Respite.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64526] = { id = 64526, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mysterious Rifts", description = "Thank you so much for your aid, {name}. I have uncovered more relics from the codex that remain intact.\n\nThe key to finding these relics rests within the strange rifts within Korthia.\n\nI can now craft a way for you to enter these rifts, in order to gain access to these missing relics.\n\nAs before, take note of the echoes to understand what these relics look like. Please be sure to examine them before you depart.", progress = "Have you seen the missing relics?", completion = "Thank you for your continued aid. The reliquary will be restored, thanks to your diligent work.", objectives = "Examine the missing relics within the Reliquary of Remembrance and purchase a Repaired Riftkey from Roh-Suir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64527] = { id = 64527, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Observing the Chase", description = "In our observations of your kind's conflict, we have noticed a high rate of escape among the prey.\n\nThis is unadvantageous to our observation efforts.\n\nThe Observer has acquired a tool we believe will improve your ability to force conflict.\n\nBefore I give it to you, we ask that you prove your willingness to participate in such conflicts, so that we know we will receive a worthy return on this investment.", progress = "Your hesitation to set out and hunt your prey is not promising, {name}...", completion = "Excellent. We will be watching your future endeavors with great interest.", objectives = "Enable War Mode and slay 1 player within the world.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64528] = { id = 64528, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wilderling Saddle", description = "<As you slipped off of the escaped wilderling's back, it shook its saddle off at your feet. It reluctantly left your side as the night fae led it back to Keeper's Respite.\n\nReldorn in Keeper's Respite might know what to make of this gesture.>", completion = "<Reldorn laughs when he sees the saddle you're carrying.>\n\nI had wondered where that one's saddle had ended up. He has resisted every rider that has attempted companionship with it, but it appears he has finally found one he considers worthy.\n\nYou have made a very stubborn, loyal companion this day, {name}.", objectives = "Deliver Wilderling Saddle to Reldorn in Keeper's Respite.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64529] = { id = 64529, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Intact Aquilon Core", description = "<The massive devourer was clutching this aquilon power core in its fist when it died, no doubt ripped from one of the destroyed aquilon around it. The power core appears to be almost entirely intact.\n\nDeos in Keeper's Respite would be able to help you locate an aquilon that you could power with it.>", completion = "<Deos's eyes light up when he sees the intact power core you're holding.>\n\nThank the Archon! I recovered a few broken aquilon from the fight earlier, and one is missing its power core. I will restore it so that you may take it with you.", objectives = "Deliver Intact Aquilon Core to Deos in Keeper's Respite.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64530] = { id = 64530, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gravewing Crystal", description = "<This large crystal fragment shattered off of the massive construct's body. Flashes of energy crackle inside of it.\n\nThe Stonewright in Keeper's Respite would be able to use this crystal to empower a gravewing for you.>", completion = "<The Stonewright raises one eyebrow as you hand her the powerful crystal.>\n\nThis is truly a unique crystal... Luckily, I know just the stonechild worthy of it. I trust you will take good care of her.", objectives = "Deliver Gravewing Crystal to the Stonewright in Keeper's Respite.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64531] = { id = 64531, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mor'geth" }
quests[64532] = { id = 64532, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Final Relics", description = "I have excellent news, {name}. I have uncovered the last set of our missing relics! \n\nIt may be difficult for you to locate them, but I have developed the proper research to aid you.\n\nPlease, review the last of our missing relics. We are so close to finding them all!", progress = "Have you seen the missing relics?", completion = "Thank you for your continued aid. The reliquary will be restored, thanks to your diligent work.", objectives = "Examine the missing relics within the Reliquary of Remembrance and purchase Research Report: Ancient Shrines.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64541] = { id = 64541, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cost of Death", progress = "Here to trade, Maw Walker?", completion = "With so many more interlopers in the Maw I need to secure my Stygia supply. Your efforts to keep me supplied will not go unnoticed and you always know where to find me." }
quests[64546] = { id = 64546, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Visions of Sire Denathrius", objectives = "It appears I am at your mercy of your whims, {name}.\n\nAs a creation of Theotar, I am obliged to attend your court whenever you wish.\n\nI suppose I shall be seeing you soon...", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64549] = { id = 64549, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legend of the Animaswell", description = "<This appears to be an incomplete set of notes detailing one archivist's search for a mythical font of anima hidden somewhere deep in Korthia.\n\nWatcher Vesperbloom in the Heart of the Forest would be able to help you put together a team to search for it.>", completion = "<Watcher Vesperbloom carefully studies the documents you brought her.>\n\nThe documentation is incomplete. It is unclear if the archivist even survived...\n\nBut the tales of the anima are incredible, and there are enough details here to launch an expedition.\n\nIt will not be easy. The archivist warns of many dangers protecting the anima source...", objectives = "Deliver Legend of the Animaswell to Watcher Vesperbloom in the Heart of the Forest.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64551] = { id = 64551, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legend of the Animaswell", description = "<This appears to be an incomplete set of notes detailing one archivist's search for a mythical font of anima hidden somewhere deep in Korthia.\n\nMerick Feldscar in the Seat of the Primus would be able to help you put together a team to search for it.>", completion = "<Merick Feldscar carefully studies the documents you brought him.>\n\nThe documentation is incomplete. It is unclear if the archivist even survived...\n\nBut the tales of the anima are impressive, and there are enough details here to launch an expedition.\n\nIt will not be easy. The archivist warns of many dangers protecting the anima source...", objectives = "Deliver Legend of the Animaswell to Merick Feldscar in the Seat of the Primus.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64552] = { id = 64552, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legend of the Animaswell", description = "<This appears to be an incomplete set of notes detailing one archivist's search for a mythical font of anima hidden somewhere deep in Korthia.\n\nKoros in Elysian Hold would be able to help you put together a team to search for it.>", completion = "<Koros carefully studies the documents you brought him.>\n\nThe documentation is incomplete. It is unclear if the archivist even survived...\n\nBut the tales of the anima are coherent, and there are enough details here to launch an expedition.\n\nIt will not be easy. The archivist warns of many dangers protecting the anima source...", objectives = "Deliver Legend of the Animaswell to Koros in Elysian Hold.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64553] = { id = 64553, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legend of the Animaswell", description = "<This appears to be an incomplete set of notes detailing one archivist's search for a mythical font of anima hidden somewhere deep in Korthia.\n\nTactician Sakaa in Sinfall would be able to help you put together a team to search for it.>", completion = "<Tactician Sakaa carefully studies the documents you brought her.>\n\nThe documentation is incomplete. It is unclear if the archivist even survived...\n\nBut the tales of the anima are incredible, and there are enough details here to launch an expedition.\n\nIt will not be easy. The archivist warns of many dangers protecting the anima source...", objectives = "Deliver Legend of the Animaswell to Tactician Sakaa in Sinfall.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64554] = { id = 64554, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Venthyr Assault", description = "The Jailer's forces  have been caught off guard by our attack. We shall overrun Perdition Hold and defeat his champions at the Altar of Domination!\n\nYour help is needed Maw Walker. Assist our forces on the battlefield!", objectives = "Complete 1 quests in Perdition Hold and the Face of Oblivion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64555] = { id = 64555, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Surveying Secrets", description = "Each of the covenants have provided their own specialists in their areas of expertise. A few of them have taken to the field to scout this unknown land.\n\nSpeak with them. They should all be keeping a report of their survey. Return them to me.", progress = "Have you found all of the scouts?", completion = "Most of this information is useful. My thanks, Maw Walker.", objectives = "Speak with the forward scouts in Korthia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64556] = { id = 64556, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Need of Assistance", description = "The inhabitants of Korthia have been through much. Were it not for our arrival, the Jailer's forces would have rampaged through the remainder of the City of Secrets, leaving destruction in their wake.\n\nTo continue our efforts, we must assist those in need.\n\nHeed the call of our allies, Maw Walker. See to it no stone is left unturned and no ally of the Jailer left alive.", completion = "This work brings us one step closer to ending Zovaal's reign over this forsaken land.", objectives = "Complete 3 Daily Quests from Mikanikos, Ta'nasi, and Kael'thas throughout Korthia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64557] = { id = 64557, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Darkness, Found", description = "Cartel Ve has a reputation for creeping around dangerous places in search of treasure. If they had any sense, they would leave the acquisition and sale of goods to the Xy. Alas.\n\nOne Ve member disappeared into Torghast with a plundered box of powerful items that he assumed would help him explore in safety. Madness!", completion = "Step no closer! Reveal yourself!", objectives = "Find Ve'nish in Torghast, Tower of the Damned.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64560] = { id = 64560, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anima Reclamation", description = "Our efforts here need a constant supply of troops, supplies, and anima. The last one is the hardest, for obvious reasons. But I've learned to be resourceful. \n\nNearby there is a plentiful source of anima: the devourers that currently swarm the Sanctuary of Guidance. It's not as easy as beating it out of a soul, but it's just as effective, if you're strong enough. Are you?", progress = "Every drop of anima we reclaim is a potential weapon against the Jailer.", completion = "You can trust me with this anima. I will see it is turned against the Jailer and his forces.", objectives = "Reclaim 8 Devoured Anima from devourers at the Sanctuary of Guidance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64561] = { id = 64561, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Observational Records", description = "Greetings, Maw Walker, a moment of your time?\n\nAs you no doubt know, my cartel has quietly spread observational devices all across Korthia. But that data is no good to us if it is not retrieved. Which is where you come in.\n\nThe records from the Windswept Aerie and Estuary of Awakening should be ready to collect. You won't see the devices themselves, but the data will appear to you as a bright orb.\n\nAnd don't forget to look below ground!\n\nBring those data to me, and I will reward you handsomely.", progress = "Have you retrieved the observational records from the Windswept Aerie and Estuary of Awakening?", completion = "Places like the Aerie and Estuary must have been desolate, even before all the destruction. What interesting creatures congregate there.\n\nWill they all survive these changes, or will some adapt, and become even more fearsome?\n\nAnd here is your reward, as promised.", objectives = "Collect 5 Observational Records from the Windswept Aerie and Estuary of Awakening in Korthia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64562] = { id = 64562, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Need a Healer - You!", description = "There are too many wounded on the battlefield! \n\nNot everyone can 'bash it and make better.' We need more healers.\n\nYou, take my device and get our wounded back on their feet!", completion = "That got them back on their feet!\n\nAny little bit helps to keep us in the fight.", objectives = "Restore 10 Wounded Covenant Allies in Seeker's Quorum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64567] = { id = 64567, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Missing Scholar", description = "Ah, Maw Walker. Your return blesses us with great optimism, and much needed assistance.\n\nSeveral scholars remain unaccounted for. We believe they were last seen studying in the great court. We fear they may be lost, or worse, taken by those who seek to disrupt our way of life.\n\nReturn to me when you have answers.\n\nMay the path guide you.", completion = "How... how did you find me?", objectives = "Locate Scholar Roh-Suir in Korthia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64571] = { id = 64571, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tazavesh: Seek and Do Not Destroy" }
quests[64579] = { id = 64579, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hollow Efforts", description = "The large metal spheres that litter the landscape of Zereth Mortis are spent forges, discarded during the creation process. \n\nThese empty metal husks still contain residual materials of creation that may be useful to us.\n\nUse my Forge-Tap near these metal spheres to harvest any Remnant Neomotes. You may also find other useful proto-materials!", progress = "Have you gathered the materials already?", completion = "Excellent work, {name}. These resources will bolster our efforts here.", objectives = "Collect 40 Remnant Neomotes from Progenitor Forges using Firim's Forge-Tap.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64581] = { id = 64581, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gently Shaken Gift", objectives = "This present looks like it has been shaken a few times. The tag on it reads:\n\nTo a very special {race} {class}.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64582] = { id = 64582, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Yuni-Test" }
quests[64592] = { id = 64592, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Historic Protection", description = "The outsiders have disrupted the sands. We cannot reach the terraforming records we need in order to collect necessary historical information.\n\nWill you assist us?\n\nHelp Mai Obet collect historical records in the Endless Sands.", completion = "We have archived the necessary records. Thank you for your assistance.", objectives = "Help Mai Obet examine 6 Terraforming Records in the Endless Sands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64597] = { id = 64597, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sanctum of Domination - Damned If You Don't", description = "I feel Kel'Thuzad's presence in these halls. Claim shards from his phylactery and I'll be able to open a new pathway into his chambers.\n\nFour shards should be enough. We wouldn't want him coming back again would we?", progress = "Four shards should allow us to access his chamber.", completion = "This should help us gain access to his chamber more readily.", objectives = "Collect 4 Phylactery Shards from Kel'Thuzad within the Sanctum of Domination on Normal Difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64598] = { id = 64598, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sanctum of Domination - Damned If You Don't", description = "I feel Kel'Thuzad's presence in these halls. Claim shards from his phylactery and I'll be able to open a new pathway into his chambers.\n\nFour shards should be enough. We wouldn't want him coming back again would we?", progress = "Four shards should allow us to access his chamber.", completion = "This should help us gain access to his chamber more readily.", objectives = "Collect 4 Phylactery Shards from Kel'Thuzad within the Sanctum of Domination on Heroic Difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64599] = { id = 64599, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sanctum of Domination - Damned If You Don't", description = "I feel Kel'Thuzad's presence in these halls. Claim shards from his phylactery and I'll be able to open a new pathway into his chambers.\n\nFour shards should be enough. We wouldn't want him coming back again would we?", progress = "Four shards should allow us to access his chamber.", completion = "This should help us gain access to his chamber more readily.", objectives = "Collect 4 Phylactery Shards from Kel'Thuzad within the Sanctum of Domination on Mythic Difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64607] = { id = 64607, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tazavesh: A Hard Bargain", description = "Ah, my work looks marvelous on you. You are the very image of legitimacy!\n\nAnd now that I've provided you with my talents, you shall provide me with yours. Seek out my business associate, Fe'tajid, at the Gilded Landing and offer him your assistance.\n\nI look forward to hearing of your success.", progress = "Have you spoken with my associate?", completion = "It seems our efforts to deceive the Zo were unsuccessful. But their efforts to kill you failed as well, so no harm done, yes?\n\nPerhaps a more generous reward is in order. Please accept this, along with my sincerest gratitude.", objectives = "Seek out Au'manal's business associate and offer your assistance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64639] = { id = 64639, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Winter Veil Gift", objectives = "A small tag on this present reads:\n\nHappy holidays, {name}!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64640] = { id = 64640, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "AubriesTestQuestForJeff" }
quests[64641] = { id = 64641, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mysterious Greenery", description = "There's a bright power emanating from the place above. I'm drawn towards it, like a moth to a light!\n\nI want to check it out, whatever it is. Won't you join me, please? It'll be so fun!", completion = "We are Circle Koh of the jiro.\n\nWe are here to fix this land.", objectives = "Visit the Untamed Verdure with Glimmercane.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64642] = { id = 64642, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clearing the Ruins", description = "This place was abandoned for too long. The vegetation has overtaken the land.\n\nWe must enter the Blooming Foundry to fix it.\n\nUntil then: clear the area. Remove the deviants who have grown twisted over time.", completion = "This is a good start.", objectives = "Kill 15 creatures within the Untamed Verdure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64643] = { id = 64643, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scavenging a Solution", description = "The Blooming Foundry created this area. It maintains the automa, the creatures, and the plants.\n\nThe overgrowth is its fault.\n\nWe need to enter the Foundry to fix this land. This constructor can break through when it is working.\n\nMany automa in this area stopped moving long ago. Find usable pieces inside them.", progress = "With your help, we will restore this place to its glory.", completion = "This will work.", objectives = "Find 8 Automa Internals from Abandoned Automa in the Untamed Verdure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64644] = { id = 64644, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Splash of the Eternal", description = "I don't really know much about this place or its inhabitants, but what I do know is magic! I can sense ancient power from the waters near us.\n\nMaybe that can help?\n\nLet's check out that pond!", progress = "<The automa lies inert.>", completion = "<A small opening in the creature looks like the perfect size for a little pour of mystical water.>", objectives = "Help Glimmercane extract water from the pool in the Untamed Verdure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64645] = { id = 64645, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moment of Truth", description = "Our constructor is ready.\n\nWe shall start the process to open the Blooming Foundry and reset this land.\n\nWe can start over.", completion = "On to the Foundry.", objectives = "Follow the Koh jiro in the Untamed Verdure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64646] = { id = 64646, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ramping Up", description = "We must restore the Foundry's power to use it. Conductors will channel power so we can use it.\n\nWe know how to use the conductors. Clear the way, and we shall start over.", completion = "These automa should not act like this.\n\nThey are beautiful. Strange. New.\n\nWe must deliberate before continuing.", objectives = "Activate 4 conductors within the Blooming Foundry.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64647] = { id = 64647, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strange Gears", description = "<Oddly, the seed within the automa's innards is still very much alive.\n\nAre they all like this?>", progress = "These are very unusual.", completion = "<Koh Shira examines the piece of the automa--entwined with living vines.>\n\nThis cannot be.\n\nAutoma do not have vines within them. But these automa do.\n\nThis... is beautiful.", objectives = "Collect 3 Winding Seeds from the automa in the Blooming Foundry.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64648] = { id = 64648, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reap What We Have Sown", description = "We told the constructor that we will use the Foundry to reset this land.\n\nWe must stop it and protect the new automa.", completion = "Learning about new creatures that are infused with living growth--well, that sounds right up my alley! \n\nI think I'll stay with them and see how I can help... and maybe pick up their language as well. \n\nThanks for coming on this adventure with me, friend!", objectives = "Defeat the Charged Constructor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64650] = { id = 64650, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hyena Soul", description = "<The Hyena Soul is fiery and spry. The shape of the hyena will be yours to call upon.>", completion = "Ah, the hyena. This shape is now yours to call upon.", objectives = "Bring the Hyena Soul to Lady Muunn in the Heart of the Forest.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64651] = { id = 64651, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cobra Soul", description = "<The Cobra Soul is covetous and protective. The shape of the cobra will be yours to call upon.>", completion = "Ah, the cobra. This shape is now yours to call upon.", objectives = "Bring the Cobra Soul to Lady Muunn in the Heart of the Forest.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64654] = { id = 64654, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Ben Howell", objectives = "You will learn:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64706] = { id = 64706, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Matter Of Motivation", description = "Giants litter these sands, mortal. But I believe we can revitalize them. \n\nThe smaller automa that are hiding in the desert can be utilized here. Use my Motivator to rally them to our cause. If we can gather enough, their energy can replenish these defeated behemoths to bolster our forces.\n\nReturn as many as you can to me, and we will put them to work!", progress = "Have they been suitably motivated?", completion = "Well done, mortal! Soon we shall see the results of your efforts.", objectives = "Return 6 Motivated Automa to Firim.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64709] = { id = 64709, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fel Path Through Time", description = "A corrupting star shines upon the land, threatening all with burning oblivion. The star betrays those who seek the light, its red glow obscuring rather than revealing.\n\nWhile its influence holds, new paths may open up to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.", completion = "Ah, {name}, you have returned. An otherworldly air hangs heavy about you.", objectives = "Complete 5 Timewalking dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64710] = { id = 64710, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whispering Felflame Crystal", description = "The crystal pulses with an eerie, felfire green glow. Holding it, you hear faint echoes of guttural demonic voices. Although the words are jumbled, one is both decipherable and repeated often: Dalaran. \n\nPerhaps someone in the city floating over the Broken Isles can tell you more about this crystal and its purpose.", completion = "I will just put this back when it belongs. Thank you for bringing it to me, {name}.", objectives = "Bring the Whispering Felflame Crystal to Aridormi in Dalaran, floating above the Broken Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64713] = { id = 64713, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Picking Up the Pieces... Literally", description = "Orbs help us develop terrain for the Forge. Magic within the orbs draws the devourers. They tear apart the metal to reach it. We must collect the remains.\n\nLook for the fragments around the orbs. Bring them to us.", progress = "Did you find the fragments? We need many pieces.", completion = "Enough to fix a small orb. This will do.", objectives = "Collect 30 Orb Fragments.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64717] = { id = 64717, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Materials of Creation", description = "The large metal spheres that litter the landscape of Zereth Mortis are spent forges, discarded during the creation process.\n\nThe spheres near the Forge of Afterlives contain trace amounts of materials unique to that location.\n\nI have modified my Forge-Tap to harvest those materials.  Use it near the forges I have identified. The rare Eidolic Fragments have the greatest chance to be found on the largest of Progenitor Forges.", progress = "Have you collected what we need?", completion = "I shall make use of these immediately. These will help Saezurah and the automa resist the effects of the domination magic.", objectives = "Collect 10 Eidolic Fragments and 300 Minor Enigmet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64718] = { id = 64718, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keys To Victory", description = "The song... incomplete. Harmony is needed. Seek those who scry. Send them to serve the cycle.\n\nMawsworn hold the keys that bind. Take the keys, set them free.", completion = "The chorus gathers. Soon, our voices will merge.", objectives = "Free 6 Automa Scryers from their cells.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64720] = { id = 64720, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleaving A Path", description = "Maw Walker! My scouts report that the Mawsworn have dominated two automa Oracles to aid them in battle. These Oracles will most certainly predict our strategy and our ultimate goal, if given the chance.  \n\nWe need to eliminate both Oracles before we enter the Crypts. With them out of the way, the Mawsworn troops won't know what we're doing until we're finished with it.\n\nTake Emeni with you. She's eager for battle.", completion = "Perfectly executed, {name}. The loss of those Oracles should keep the Mawsworn in the dark.", objectives = "Slay Oracle Zoketh and Oracle Voraxxi.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64722] = { id = 64722, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knocking On Death's Door", description = "This is it, mortal. The forces you have assembled should be enough to break through the Mawsworn and reach the Crypts. Getting inside, however, will require more effort. The Mawsworn have barricaded the entrance.\n\nKbato will carry you into battle. Eliminate the Mawsworn, and destroy the devices that power the barrier.", completion = "By the First Ones... I never dreamed I would see this place with my own eyes.", objectives = "Riding Kbato, defeat the Mawsworn forces in the Endless Sands and open the way to the Crypts of the Eternal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64723] = { id = 64723, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restoration Project", description = "Without an Arbiter, the very purpose of the Shadowlands has been compromised. Souls flood the Maw with no direction.\n\nAs Saezurah noted, Zereth Mortis would ordinarily craft a new being to take the Arbiter's place. I suspect the Jailer's forces have disrupted the land to the point where this is no longer possible.\n\nIt is time to take action ourselves, and bring stability again to the Shadowlands! Speak to Saezurah, and see where we must begin.", progress = "Have you spoken with them?", completion = "The covenants are certain to send aid if we ask.", objectives = "Speak with Saezurah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64725] = { id = 64725, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unforgivable Intrusion", description = "Darkness spreads dissonance throughout these halls. Mawsworn drain life from the air, and give only suffering in return. This must not be.\n\nIf the song is to be restored, silence is needed. The Mawsworn must be destroyed.", progress = "When the halls are silent, we may proceed.", completion = "The golden hour of silence. A space for creation to begin.", objectives = "Eliminate 6 Dominated Automa and 3 Darkseer Corrupters.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64726] = { id = 64726, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Order Of Things", description = "Essences of ancient souls, tampered with--they bleed from each room. The halls must be restored, the flow of souls redirected.\n\nThe spheres hold the key. Seal the breaches, restore the flow, then the vessel may be filled.", progress = "Seal the breach, restore the flow.", completion = "A breath held--anticipation. Soon, the soul will merge, and the song of creation will begin." }
quests[64727] = { id = 64727, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Infinite Circle", description = "Creation calls--can you hear it? Yet darkness lingers below, taints the ancient melody.\n\nTo forge anew, peace must be restored. The Walker must walk, and protect.\n\nThere is much to be done. Lead the way.", completion = "Our voices are muffled in the lingering dark.", objectives = "Escort Saezurah to the center of the Crypts of the Eternal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64728] = { id = 64728, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Acquaintances Forgotten", description = "It is time. The song shall bring life anew. Tell me when you are ready to begin.", progress = "The ritual must be completed.", completion = "Dissonance lingers. A pure tone is needed. Reset the cycle anew.", objectives = "Complete the Ritual.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64729] = { id = 64729, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lifetimes To Consider", description = "This song has been completed, and harmony has been restored. Yet Zereth Mortis remains haunted by discord.\n\nDissonance lingers still, outside these walls. We must leave before it finds us.\n\nSpeak with the one you call Firim--he will open the way.", completion = "I can hardly believe all we've accomplished... truly, this is a day worth remembering. We could not have achieved this without you, my friend.", objectives = "Return to Exile's Hollow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64730] = { id = 64730, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Turning Point", description = "A pause, devoid of breath. A melody lingers on. The cycle awaits a voice.\n\n<You are unsure of what Saezurah means. Perhaps you should try to set up the ritual again, starting with the Vessel and the scryers.>", progress = "Have you tried everything?", completion = "I do not wish to say it but... it seems we have failed, my friend.", objectives = "Examine the Vessel and the Automa Scryers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64731] = { id = 64731, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For Every Soul", description = "Without the Arbiter to stem the flow of souls to the Maw, the Shadowlands will never be fully repaired.\n\nThis cannot be the end. Surely you can think of something?", progress = "This moment is of great importance.", completion = "A new voice added to the chorus -- the cycle continues ever onward.", objectives = "Find a way to create a new Arbiter.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64733] = { id = 64733, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Help From Beyond", description = "If we stand any chance of breaking through the Mawsworn forces, we will need the help of all of the covenants.\n\nI will speak with the Kyrian. You and Pelagos can speak with the others. But before you go, ask Firim if there is any way we can gain the support of the Enlightened as well.", completion = "Between the strength of the covenant forces and the help of the automa, we should be able to reach the Crypts!", objectives = "Speak with representatives from the Enlightened, Venthyr, Necrolord, and Night Fae.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64739] = { id = 64739, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zovaal's Grasp", description = "I remember this metal. I saw it when I was touched by Maw magic. When I was severed...\n\nI will show you where this happened. Follow me. I will tell you my story.", completion = "It is worse than I thought. Much worse.", objectives = "Follow Hanoa the Exile and listen to her story.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64741] = { id = 64741, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Security Check", description = "I do not understand--these are my brethren! How can they be so careless, so unconcerned with both greedy cartels and the Mawsworn at their doorstep?\n\nTheir protective technology is antiquated. It will not keep danger out. If I cannot persuade them to leave, I can at least ensure they are safe where they insist on staying.\n\nI do not want to lose my friends again.\n\nThere should be four hidden conduits around the edge of the shield. Take this kit. It will allow you to inspect and repair them, if needed.", progress = "Should those conduits fall, we will need to construct additional ones. Nobody wants that.", completion = "I knew it! Haven's defenses were deliberately tampered with -- by Cartel Xy!", objectives = "Investigate the Shield Conduits around Haven.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64742] = { id = 64742, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Traces of Tampering", description = "So the shield has been sabotaged. Of course the ruthless Cartel Xy are the first to attempt to profit off this land. \n\nTheir greed has put us all in even more danger. We must stop them. Let us search together for signs of their passage.", completion = "Cartel Xy is nearby.", objectives = "Find clues of Cartel Xy's presence.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64743] = { id = 64743, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Xy Are You Doing This?", description = "We cannot see them, but I am certain this is where Cartel Xy has established their base.\n\nSomething must have drawn Xy to this area of Zereth Mortis specifically, and we must discover what it is if we are to protect our friends here. \n\nTheir cloaks do not cover their supplies very well. See what information you can gather from their belongings.", progress = "We must discover Cartel Xy's intentions here.", completion = "Oh, they thought they could hide their plans with a code? Hold on, my friend, this should take just a moment...", objectives = "Gather 10 Suspicious Papers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64744] = { id = 64744, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Broker Decloaker", description = "Do you sense a shift in the air? They may be hidden, but Cartel Xy is near.\n\nFortunately, the devices they use to cloak themselves are familiar to me. Here; take this. Place it on the ground and it will reveal nearby agents... for a time. \n\nStop them, even if you must take their lives.", completion = "Their deaths are a shame, but we must protect Haven.", objectives = "Kill 12 Cartel Xy agents just outside of Haven.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64745] = { id = 64745, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Selfless Preservation", description = "The automa were once abundant here, singing, constructing various things, carrying out the purpose of the First Ones. Then, invaders from the Maw slaughtered them all.\n\nThe last automa to fall were protecting something important in a nearby structure. \n\nI witnessed one of the cursed Mawsworn steal a device by the door. The Elders say we should not meddle with artifacts, but would it be a transgression to recover what was stolen?", completion = "This automa still lives! But it is so weak.", objectives = "Recover the Stolen Artifact in the Arrangement Index and restore it to its rightful place.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64758] = { id = 64758, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Following the Leader", description = "We sealed the door to the Slumbering Vault when we first arrived. It is a sanctum, a cradle of all that is precious here. The power that sleeps within should not be touched by us. \n\nIf the Xy leader made it past the shields while we were distracted by the beauty of this place, I shudder to think of what they have already disturbed.\n\nHurry! We must go to the Slumbering Vault and ensure its safety.", progress = "Cartel Xy must be stopped!", completion = "No! What has that fool done to the console?!", objectives = "Investigate the Slumbering Vault.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64759] = { id = 64759, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Junk's Not Dead", description = "This automa has been hiding here! I suspect it will not be receptive to our help.\n\nI am hesitant to suggest this, but if the servitor were to associate you with this facility, it might be more amenable. \n\nIf you have the means, copy the glyphs inscribed on similar automa outside. Those that the Maw have touched will be tainted, but I saw from my vantage point a few fallen automa in the sands with untarnished glyphs.", completion = "I hope this will encourage our friend here to view us as an ally. First Ones forgive us.", objectives = "Obtain glyphs from 6 Depleted Servitors around the Arrangement Index.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64760] = { id = 64760, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Technical Difficulties", description = "The console is going haywire! We have to fix it!\n\nMaybe these buttons do something?", progress = "We have to fix the console somehow!", completion = "Thank you for your assistance, Maw Walker.\n\nI must return to Oribos. I will tell Cartel Al that our friends are not lost, but Enlightened.", objectives = "Press buttons on the console in the Slumbering Vault.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64761] = { id = 64761, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Core Competency", description = "The poor thing.\n\nThe sacred should not be disturbed, but... will the elders judge us if we help it survive? This is preservation, not interference.\n\n...I hope. \n\nWe can power it back up. Use this depleted core as a conduit. Perhaps the larger wild animates in the nearby sands have enough energy to charge it.", completion = "This lonely one will be strong again.", objectives = "Charge a Depleted Automa Core by draining slain wild creatures in the Arrangement Index.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64762] = { id = 64762, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Revival of the Fittest", description = "This core is brimming with energy!\n\nUse the charged core to revive the automa. Hopefully, it will no longer see us as a threat.\n\nDo be careful. The power of the First Ones is not meant for us to control.", completion = "Support has arrived. The restoration may commence.", objectives = "Revive the Hidden Servitor in the Arrangement Index.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64763] = { id = 64763, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maintenance Mode", description = "The architect set forth these tasks: \n\nStay safe. \n\nRestore the Protoform Repository when danger passes.\n\nThe mortal knows the cyphers. The mortal will help with the tasks.\n\nAttuning of the energy terminals is required. Each terminal requires a codex. Invaders pilfered the necessary codices. \n\nGo.", completion = "The tasks are in motion.", objectives = "Attune 4 Energy Terminals in the Arrangement Index.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64766] = { id = 64766, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Access Request", description = "The architect alone possesses the Restoration Matrix required for the restoration. The architect will restore the Protoform Repository.\n\nThe mortal will gain access to the Chamber of Shaping and inform the architect of recent progress. The architect will restore the repository.\n\nFulfillment of the task is imminent.", progress = "The architect will assist us.", completion = "The Restoration Matrix is acquired. The architect is not present. The architect is therefore lost. \n\nRestoration of the repository is mandatory, even so.", objectives = "Find the Proto Architect in the Chamber of Shaping and retrieve a Restoration Matrix.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64767] = { id = 64767, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Final Song", description = "Servitors do not possess the strength to restore the repositories. Nevertheless, the task must be completed.\n\nThe mortal must stay close to protect the restoration process.\n\nCome.", completion = "I should have obeyed the elders! This is all my fault!", objectives = "Stay near Kodah while keeping enemies away to capture the Protoform Repository.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64768] = { id = 64768, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lightsprocket's Artifact Hunt" }
quests[64771] = { id = 64771, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enlightened Exodus", description = "Hello, my friend!\n\nAn expedition of Cartel Al was sent in search of this place long ago, and was believed lost. I entered Zereth Mortis in hopes of saving my splintered cartel from the dangers of the Maw that have preceded me.\n\nAt last, I have found my old friend! And yet, she refuses to return to safety.\n\nPerhaps others can be convinced. Will you try?", progress = "Have any others chosen to leave?", completion = "If they cannot be persuaded, they must be protected.", objectives = "Talk to the Enlightened around Haven.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64772] = { id = 64772, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Broken Circle", description = "The jiro of Circle Olea work here. We make...\n\n<The jiro pauses for a moment.>\n\nThey... make new lands and creatures for the Forge.\n\nDevourers attacked, but some jiro still survive. You must find them. Tell them to gather outside the cave to the north. I will clear the way.\n\nDo not tell them I sent you. They will not want to see me.", completion = "Thank you for finding the survivors!", objectives = "Find any surviving jiro and convince them to meet outside the cave.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64773] = { id = 64773, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Jiro Guide to Not Being Eaten", description = "Devourers attacked. They overran the guardians. They still search for food.\n\nWe are not safe. Reduce the devourers' numbers.\n\nThis is how not to be eaten.", progress = "Is it safe? There are so many devourers...", completion = "Fewer devourers, less likely we will be eaten.", objectives = "Reduce the devourer presence at the Terrace of Formation.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64775] = { id = 64775, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mawdified Behavior", description = "There is a devourer in the cave. It creates a rift. This should not be possible in Zereth Mortis.\n\nEnter the cave and destroy the devourer. Search for clues. See how it can open a rift.\n\nBe careful. This one is different from others. It has absorbed the magic of the First Ones. This has never happened before. Be ready for anything.\n\nI will stay here and protect the jiro.", progress = "Is the devourer destroyed? Did you find any clues?", completion = "A new type of devourer. Troubling. Hopefully these are the only ones.\n\nAs for this mysterious metal... I have seen it before.", objectives = "Kill the Unraveller and search it for clues.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64778] = { id = 64778, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rift Recon", description = "Devourers are a problem. Rifts are a bigger problem. \n\nThey will keep bringing devourers. We must close them. To do this, we need information. \n\nTake the crescendal. Use it to analyze the rifts. Bring the information back to us.", progress = "Do not break the crescendal. It can be... difficult to use.", completion = "This information will help us. Tell us how to close the rifts. Fewer rifts means fewer devourers.", objectives = "Analyze 6 Warped Rifts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64779] = { id = 64779, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pound of Flesh", description = "Automa remove threats to us. But there are no more automa. We must help ourselves. We need magic.\n\nDevourers ate the orb magic. Now they are warped and twisted. But also full of magic.\n\nBring us devourer flesh. We will extract the magic. We will need it to defeat the devourers.", progress = "Devourers were not meant to eat this magic.", completion = "This is the flesh {name} gathered? \n\n\n\nIt will have to do.", objectives = "Collect 30 Warped Flesh from devourers at Zovaal's Grasp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64780] = { id = 64780, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mawsteel, Maw Problems", completion = "Removing mawsteel prevents rifts. It is not much but it will help.", objectives = "Lift 4 Mawsteel Shards and throw them off the cliffs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64783] = { id = 64783, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dance Dance Darkmoon", description = "Simon says, \"Are you ready to dance?\" Step on in and show off your sweet moves, {class}.\n\nThe rules are simple. Your opponent will perform a series of stylish moves, then you gotta match 'em.\n\nEarn enough accolades and then come back to ol' Simon. Just know that the more challenging the opponent, the more accolades you can earn.\n\nSimon says, \"Are you up for the challenge?\"", progress = "Simon says, \"Show me what you got.\"", completion = "Simon says, \"Those were some sweet moves, {name}.\" \n\nSimon is impressed!", objectives = "Earn accolades by competing in the dance competition.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64784] = { id = 64784, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "9.0 Rated PvP Incentive - Shadowlands Season 2 Exclusive Mount" }
quests[64785] = { id = 64785, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Overgrown Story", description = "Since our arrival here the Untamed Verdure has been a mystery waiting to be solved. The lush foliage of the area grows on everything as the creatures run amok without purpose.\n\nThere could be valuable research data to be obtained from these creatures.\n\nUse a Containment Trap to subdue the elemental creatures. Once subdued, examine them for research data.", completion = "This information will help, but I'm afraid those ruins still remain a mystery!", objectives = "Gaiagantic and 12 Geomentals examined for research data.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64794] = { id = 64794, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knowing is Half the Battle", description = "{name}, you should join Shandris and infiltrate the Mawsworn forces from the east. Whatever information you two uncover will inform us of your next course of action.\n\nTake care. We have no information on what you may find.", completion = "You've arrived.\n\nTheir movements here are strange. It almost seems as if the bulk of their forces are elsewhere.", objectives = "Meet Shandris near the Provis Strata.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64796] = { id = 64796, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scour the Sands", description = "The little I have seen so far has given me almost no information about our enemies. We will have to take a closer look.\n\nI can hide the both of us from sight on your command. But stay away from the dreadlords--their eyes are sharp enough to spy even a hidden huntress.", progress = "The less attention we draw, the better.", completion = "We have discovered their immediate goal. We should return to our allies, quickly.", objectives = "Scout Provis Strata with Shandris Feathermoon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64797] = { id = 64797, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harmony and Discord", description = "These obelisks must be key to Zovaal's plans. Even without full knowledge of their purpose, we should stop the Mawsworn from meddling with them.\n\nI will bring this information to Highlord Bolvar. Head to Darion Mograine and do the same. He will need to plan his defenses around this.", completion = "The enemy has not yet been able to break through our defending line, but I fear we will lose the battle without your assistance.", objectives = "Speak with Darion Mograine at Provis Terra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64798] = { id = 64798, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What We Overcome", description = "I understand now. All of us that were touched by Domination were able to tap into something. Whether nobility or vengeance, it gave the strength to resist.\n\nWith all that I have faced, I have to remember that I am still here.\n\nAnd if there are those willing to stand with Sylvanas, I have to believe they will stand with me as well.\n\nI'm ready to try again. This time, I will overcome whatever I face.", progress = "We will not fail. There is no other choice but oblivion.", completion = "All the shards are now infused with the resistance we gained from our experiences with Domination.\n\nIt was not easy, for any of us. But I am proud of what we were able to accomplish, together.\n\nAs for the rest, our future is in the hands of the Primus.", objectives = "Defeat the Mawbound Monstrosity and infuse the final shard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64799] = { id = 64799, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Broken Crown", description = "Our friends have returned from the Sepulcher of the First Ones with a familiar face.\n\nAnduin... What terrible things he has endured. \n\nBut as difficult and painful as it is, we must uncover what he knows. The Jailer has blocked our way within the Sepulcher, and we risk falling victim to Domination ourselves if we blindly follow.\n\nHe is our best hope.", progress = "We must defeat Zovaal, or all is lost.", completion = "The suffering he endured... \n\nThis will be difficult to overcome.", objectives = "Speak to Anduin Wrynn in the Geometric Cavern.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64800] = { id = 64800, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Our Last Option", description = "Zovaal has blocked our pursuit. If we are to defeat him, we must find a way to withstand Domination.\n\nBut to overcome it, we need to understand how it works. \n\nThe Primus of Maldraxxus created Domination, he will be able to tell us more.\n\nI asked Taelia to bring a piece of the Helm of Domination to Zereth Mortis. I dread to think of what might happen were I to try to carry it again... \n\nLet us discuss the way forward.", progress = "We can never turn things back to the time that was. We can only live with the choices made, and move forward.", completion = "I don't like this as an option any more than Taelia does, but we need to wield Domination safely if we are to find a way to overcome it.\n\nOur first step is to ensure that the helm still works. On us.", objectives = "Listen to the plan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64801] = { id = 64801, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elder Eru", description = "Since we have earned the trust of the Enlightened, I have learned more about their explorations into Zereth Mortis.\n\nThey know more than they are willing to tell, but often do not act on that knowledge. Perhaps where they observe, we can be a catalyst for action.\n\nIn a secluded corner called the Lexical Glade, there is an elder named Eru. She may be able to give us insight on how we might use the language of the First Ones.\n\nSeek her out, and see if she will help us.", completion = "What is this? You wish to know if there is anything here that can help you resist Mawsworn magic?\n\nYou are in luck, stranger. I happen to know that this place is a library. And libraries are wonderful places to find what you are looking for.", objectives = "Find Elder Eru outside the Lexical Glade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64802] = { id = 64802, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hello, Darkness", description = "I created Domination as a tool to punish Zovaal.\n\nMy anger informed that creation, and now we pay the price for my hubris. Even Eternal Ones err on occasion.\n\nBut we are not without hope.\n\nTake the half of the broken Helm of Domination, and test it upon one of your own. If it retains enough power, it can then be used to test it elsewhere in Zereth Mortis.", progress = "We will not give up until we have stopped Zovaal.", completion = "Even those who overcame Domination are not entirely immune to it now.\n\nBut there may be something buried in that history that can aid us. \n\nI will think on this.\n\nFor now, focus your efforts on the creatures of Zereth Mortis. See what makes them more resistant.", objectives = "Test the broken Helm of Domination on Darion Mograine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64803] = { id = 64803, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Testing One Two", description = "The creatures of Zereth Mortis have existed here since well before I created Domination.\n\nWe have seen the effects that Zovaal's forces have had on them, but I believe there is more to be learned.\n\nUse the helm on the denizens of Zereth Mortis and see what you can uncover about a natural resistance.", progress = "You have an object that wields Domination, yet you are not overcome? Interesting.", completion = "The more advanced creatures resist Domination for longer? \n\nWell of course, I could have told you that. It's all about the language!", objectives = "Test the Broken Helm on creatures in Zereth Mortis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64804] = { id = 64804, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cryptic Catalogue", description = "This area is a repository of various texts. Hmmm? What do they say? I have no idea!\n\nI have dedicated myself to their catalogue and organization. This is more important than ever, with invaders destroying the balance in Zereth Mortis! We must preserve what we have found so far.\n\nYou can help. Go into the glade and memorize the phrases there, then meet me down in the grotto. There is something in it that might help you test that helm of yours further.", progress = "Think how much we could learn if we understood the intentions of the First Ones.", completion = "This place is wondrous.\n\nI could spend all of my existence here.", objectives = "Memorize Phrases in the Lexical Glade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64805] = { id = 64805, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Not-Scientific Method", description = "The language of the First Ones is not static like most others. It evolves.\n\nCreatures like the sentries are more advanced than your average poultrid, obviously. Their more complex thought processes give them an innate resistance to the invaders' overriding magic. \n\nBut you should not take my word for it. We can actually test this! \n\nIn the grotto there is a librarian. Take those phrases you memorized and infuse them into it. Then try out your helm.", completion = "You see! It took far longer for Domination to overtake the librarian's native purposing.\n\nOf course it did fail in the end, but I would call that a success for your particular interest.\n\nDo not worry, another automa will take that one's place. There must always be a librarian.", objectives = "Test the Broken Helm on an activated Lexicon Librarian and observe the results.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64806] = { id = 64806, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where the Memory Resides", description = "I think I know what will be asked of us in Bastion. It will not be easy.\n\nWith this half of the Helm, we have collected the first part of what is needed to resist Domination. But there are those of us who have also suffered from it. Lived through it. \n\nIn a way, it has marked us. All of us.\n\nThere must be something in those experiences that will help us break free from Zovaal's influence.\n\nLet us go to the Chamber of First Reflection in Bastion.", completion = "Good, you've arrived.\n\nWe have assembled those who have suffered from Domination in the past. Some more recently than others. \n\nAll have come through it, not always intact, but we are still standing. That is what we must capture.", objectives = "Meet Highlord Bolvar inside the Chamber of First Reflection in Bastion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64807] = { id = 64807, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What We Wish to Forget", description = "While the language of the Progenitors will aid us, there is another trait that will help break Domination's hold on us.\n\nAn indomitable will. \n\nThose of us who have endured before, and survived, have that inherent resistance, which we will offer up to be infused into each of the shards.\n\nThe Primus has assured me that this will work. With no other options, this is the only way. \n\nI trust that it will be worth the suffering.", progress = "We will do whatever it takes.", completion = "I feel... lighter. But I cannot forget what has brought me to here, and what must still be done.\n\nI hope that Taelia will remember what she saw... the man I am now. Not some lone figure locked away, but someone who does what is necessary for the good of all.", objectives = "Assist with the ritual and infuse the Shards of Domination.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64808] = { id = 64808, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Makes Us Strong", description = "I wish that I knew of this place sooner. Where terrible darkness could be purged from oneself, memories examined and expunged...\n\nI am willing to do whatever it takes to help defeat Zovaal, no matter the cost.\n\nThis is the only way.", progress = "It takes more than raw strength to do what must be done.", completion = "I think I understand.\n\n<Anduin steels himself.>\n\nI am ready to try again.", objectives = "Assist with the ritual and infuse the Shards of Domination.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64809] = { id = 64809, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Half of the Equation", description = "The Primus's theory about the language of the First Ones has borne out. \n\nStill, it may not be enough. \n\nWhile the Primus finalizes his plans, let us go deep into the Endless Sands to find pieces of this power to infuse the helm. \n\nDarion, Taelia, and I will meet you there to help with the Mawsworn.", completion = "The enemy is formidable, but with the strength of our arms and the power of the Broken Helm, we may be able to even the odds.\n\nThough I admit, I have an extra sense of caution with my daughter in the field.", objectives = "Travel to the Deserted Overlook.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64810] = { id = 64810, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oppress and Destroy", description = "What we seek is in the vaults of the Endless Sands. To reach them will require strength and numbers.\n\nTogether we will destroy the Mawsworn. \n\nI look forward to taking the fight directly to them.\n\nRemember, they will be vulnerable to the broken shard from the Helm of Domination.", progress = "Such magnificent desolation.", completion = "Well done. \n\nLet us hope that this is last time we see the helm used as a weapon.", objectives = "Slay Mawsworn in the Endless Sands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64811] = { id = 64811, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aggressive Excavation", description = "Elder Eru said that we could find the most complex examples of the First Ones' language out here. \n\nWe'll need to fight our way to the vaults, and then infuse the helm once we find those phrases.\n\nOn a personal note, I never thought I'd have the chance to fight alongside my father. Though with the stakes this high, it somehow feels like exactly the place I'm supposed to be.\n\nI am ready when you are.", completion = "We've done it. The broken half of the helm is infused with the most advanced pieces of the First Ones' power that we could readily find.\n\nWe are so close to success.", objectives = "Collect the Inscrutible Phrases.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64812] = { id = 64812, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forge of Domination", description = "We have all of the pieces we need. The broken half of the helm has been augmented with the complexity of the language of the First Ones, and the shards bear our memories. \n\nOur will to resist Domination.\n\nAll that remains is for the Primus to reforge the Helm, then we will be able to draw upon that combined power for ourselves.\n\nI know that it is dangerous, but it is our only hope.", completion = "How appropriate that the place I was imprisoned in will be the setting for how we free ourselves.", objectives = "Travel to The Runecarver's Oubliette in Torghast.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64813] = { id = 64813, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Crown of Wills", description = "When I created Domination, I did not foresee how much pain it would cause the realms. Not only the Shadowlands, but yours as well.\n\nIt is time we take this helm, this symbol of that magic, and reforge it anew. But, not for the same purpose it once had.\n\nLet it represent the strength of will that you and your kind possess, so that it may help us overcome and defeat Zovaal at last.", progress = "There is no going back.", completion = "This is a power unlike any I have felt before. We have made something new.\n\nIt will be our key to defeating Zovaal.", objectives = "Reforge the Helm of Domination.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64814] = { id = 64814, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle for the Forge", description = "Our forces have been holding out so far, but we have not secured the area. We could use some assistance cutting down the enemy's numbers.\n\nThis should be a simple task for you, Maw Walker.", progress = "Is it done?", completion = "We must remain vigilant. No one may pass our defenses.", objectives = "Kill 8 Mawsworn forces.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64815] = { id = 64815, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Together, We Ride", description = "The four covenants are working together here along with the automa. \n\nUnfortunately, some of our soldiers have been separated or wounded and are unable to return back here.\n\nIf you could aid them, that would help tremendously.", completion = "The fewer losses we suffer here, the longer we can hold the line.", objectives = "Aid 5 covenant forces.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64816] = { id = 64816, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reality's Doorstep", description = "The time has come to follow Zovaal into the very heart of the Shadowlands.\n\nWe must return to Zereth Mortis and finish this.", completion = "There is more work yet to do here in Zereth Mortis before Zovaal's influence will be expunged from the Shadowlands.", objectives = "Return to Zereth Mortis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64817] = { id = 64817, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Plain Sight", description = "That sound! It came from the direction of the obelisk at Provis Flora.\n\nImpossible. We've let no one through. Hurry, {name}. Follow me!", progress = "We must hurry!", completion = "They managed to hide themselves. This bodes poorly for us.", objectives = "Defend the obelisk at Provis Flora.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64818] = { id = 64818, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reinforcements May Be Necessary", description = "The dreadlords infiltrated deep into our ranks. Bolvar must know what has happened.\n\nI cannot leave my position here. Quickly, give him the news. Perhaps the Enlightened council will have advice as well.", completion = "Mograine will have the forces he needs.", objectives = "Speak with Bolvar Fordragon at Haven.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64820] = { id = 64820, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This is Your Fault, Fix It", description = "Provis Fauna is normally regulated by autonomous constructs, but there have been reports that they are no longer working.\n\nAccording to the reports, you are the one responsible for the tampering of these nodes. Which means it is on you to fix them. Take this tuner, it should help--and once they are repaired, do not meddle with them again.", completion = "With the defenses working again, hopefully the Mawsworn presence diminishes.", objectives = "Fix 5 defense nodes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64821] = { id = 64821, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nothing is True", description = "If we are dealing with dreadlords, they could be disguised as anything... including the denizens of Zereth Mortis. Fortunately we have just the thing for dispelling their illusions. \n\nSearch the fields and test the automa. If you find any dreadlords, take care of them.", completion = "That should slow down their plans. Good work, Maw Walker.", objectives = "Find and kill 4 Dreadlord Saboteurs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64822] = { id = 64822, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Break in Communication", description = "Mograine's request for reinforcements is unusual. We were already planning on reinforcing the area, and sent three different outfits his way.\n\nFrom the sound of it, none of them have arrived. See if you can find their commanders and make sure they make it to Mograine.", progress = "Have you found them?", completion = "They claimed you gave them their previous orders? Strange.", objectives = "Reassign orders to three covenant commanders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64823] = { id = 64823, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Doppelganger Duel", description = "Something about this doesn't sit right with me. From what you reported, this seems like intentional sabotage from within our ranks... or the work of more dreadlords. \n\nIf dreadlords are involved, then the obelisk may be at risk! Get to it--if we linger on this it may be too late!", progress = "Time is of the essence here.", completion = "Mal'ganis...\n\nWe are losing this race.", objectives = "Find the Mawsworn presence at the Circle of Thought.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64824] = { id = 64824, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fighting for the Forge", description = "We made our way here as soon as we could. Anduin has been sighted near the structure in the middle of this land, referred to as the Forge of Afterlives.\n\nNo doubt the Jailer will join him soon. We need to leave immediately.", completion = "Anduin...\n\nWe'll save you somehow.", objectives = "Head to the Forge of Afterlives with Jaina.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64825] = { id = 64825, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeking Haven", description = "I am at a loss.\n\nWe have no way to follow Zovaal and Anduin. I'll open a portal back to Haven. We will discuss our next steps there.", completion = "We will look into how to follow them into the Sepulcher. Until then, you should focus your efforts on more immediate issues.", objectives = "Return to Haven with Jaina and Baine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64829] = { id = 64829, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finding Tahli", description = "After eons of tranquility, the Maw's influence has brought sorrow to Zereth Mortis. One of our acolytes, Tahli, has found it particularly difficult to process recent events. She left some time ago and has not returned. \n\nWill you check on her? She was last seen heading toward the ruins that are buried under the sands.", completion = "Even now, this place is beautiful.", objectives = "Find Tahli near the Arrangement Index.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64830] = { id = 64830, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enlisting the Enlightened", description = "The fate of Sylvanas is not my immediate priority.\n\nThe Jailer has destroyed the Harmonic Channels, ensuring that we cannot follow him. \n\nPerhaps the studious Enlightened Brokers know something about these channels that will help us--but broker cooperation comes often with strings attached. \n\nDo whatever they demand. We must learn more.", completion = "Zereth Mortis has the answers you seek.\n\nIf you know where to look.", objectives = "Persuade the Elders of Haven to offer their assistance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64831] = { id = 64831, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Remnants of the First Ones", description = "Some evidence of the Mawsworn's destruction may remain in Provis Esper. Recovering that evidence will provide some clue as to how to follow this Jailer.\n\nLet us hunt together. I will know the sign of the First Ones's magic when we are in its vicinity.", progress = "Have we found all of the remnants?", completion = "Only inert remnants, unfortunately.\n\nBut do not lose hope, my friend!", objectives = "Collect 3 Conduction Remnants.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64832] = { id = 64832, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reclaiming Provis Esper", description = "Provis Esper is overrun with devourers, buzzing around like hungry vespoids.\n\nThey are destroying the local automa, which is not at all what the First Ones intended. A cleansing is in order.\n\nFor our safety and to restore the natural order, clear some of them out.", progress = "Have you cleansed Provis Esper?", completion = "More devourers will come, but you have lessened their impact for now.", objectives = "Kill 20 Insatiable Mites, 5 Soul-Parched Gorgers, and 2 Reality Breachers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64833] = { id = 64833, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forging Unity from Diversity", description = "The other Elders follow a strict interpretation of how best to honor the works of the First Ones.\n\nI am not so inflexible. Our end goal is the same. \n\nLet us return to the area where you last saw the Jailer.", completion = "The site below is crawling with devourers. But you can manage, yes?", objectives = "Meet Elder Ara above Provis Esper.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64834] = { id = 64834, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glow and Behold", description = "Look, {name}. The remnants are faintly glowing!\n\nThey must be reacting to something in Pilgrim's Grace.\n\nFind out what is causing this reaction!", progress = "The remnants reacted to this translocator? Incredible!", completion = "So the remnants have something to do with the translocator. But what?\n\nWhatever their prior function, they have no power now.", objectives = "Locate what is causing the Conduction Remnants to react.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64835] = { id = 64835, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pluck from the Vines", description = "I ran, scrambling through the thorny foliage, the lashers snapping at my heels.\n\nMy fellow pilgrims were not so lucky. I could hear their screams of pain and horror as I fled.\n\nYou must find a way inside. Rescue them, {name}!", progress = "Have you rescued the missing pilgrims?", completion = "I cannot thank you enough for rescuing the pilgrims who could be saved.", objectives = "Rescue 5 missing pilgrims.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64836] = { id = 64836, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nip It in the Bud", description = "The Catalyst Wards used to be peaceful. Pilgrims have been coming here for ages to observe the wonders of the First Ones. But this place is no longer safe. The Cultivator showed no mercy and no reason as it slew several of our brethren.\n\nYou must destroy it.\n\nOther Elders would disagree with me. The other Elders are wrong.", progress = "What could have caused the Cultivator to behave so irrationally... so violently?", completion = "Putting the Cultivator down was the right call.", objectives = "Kill the Cultivator.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64837] = { id = 64837, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Pilgrim's Journey", description = "Pilgrim's Grace is a sacred site for the Enlightened. The Elders there have an intimate understanding of the creations of the First Ones.\n\nWe will find answers there about these strange remnants we have found.\n\nMeet me at Pilgrim's Grace. It is not far.", completion = "Welcome to Pilgrim's Grace.", objectives = "Meet Elder Ara at Pilgrim's Grace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64838] = { id = 64838, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where There's a Pilgrim, There's a Way", description = "If the remnants can be restored, someone in Pilgrim's Grace may know how.\n\nBegin with Elder Nirav. I hope he is willing to help. He seems anxious and distracted today.\n\nFind me in town when you are done.", progress = "Have you spoken to the Enlightened in Pilgrim's Grace?", completion = "Feroz is our best bet? And he has gone missing along with several other pilgrims?\n\nWe should hurry.", objectives = "Speak to the inhabitants of Pilgrim's Grace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64839] = { id = 64839, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Root of the Problem", description = "I suspect we can harness the growth energy present in these plants for our own purposes, but I will need fresh samples.\n\nYou can harvest energized plant matter from any of the lashers or vine-choked automa nearby, or those inside the Catalyst Wards.", progress = "Have you recovered the energized plant matter?", completion = "These roots are overflowing with growth energy.", objectives = "Collect energized plant matter.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64840] = { id = 64840, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unchecked Growth", description = "This growth energy is highly unusual. I would like to know more about how it affects the local automa.\n\nHarvest replicating essence from deceased automa in the Catalyst Gardens.\n\nBring it back to me for study.", progress = "Do you have the replicating essence?", completion = "Hmm... it replicates rapidly until it kills the host. \n\nThis is more of a curse than a gift!", objectives = "Collect 12 Replicating Essence.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64841] = { id = 64841, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Take Charge", description = "That floating structure looming overhead is the Creation Catalyst.\n\nI cannot get close to it. The tower is overloaded with an excess of Progenitor energy. To travel there now would be suicide.\n\nThere are consoles in the gardens that can be used to discharge that energy. Do so.", progress = "Is it safe to fly up to the Creation Catalyst?", completion = "Well done, Maw Walker!", objectives = "Discharge the excess energy of the Creation Catalyst.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64842] = { id = 64842, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flora Frenzy", description = "Those guardian automa will shoot down anything that attempts to reach the Creation Catalyst.\n\nMay I suggest fighting fire with fire? Or rather, fighting the creations of the First Ones with the creation energy of the First Ones?\n\nI have had little time to adequately test my theory, but this potion should provide the boost you need to destroy them... ideally without dying from exposure to the creation energy in the process.", progress = "Your safety is probable, but not guaranteed.", completion = "It was quite poetic, I think, using their own growth energy against them.", objectives = "Drink Feroz's solution and destroy the automa of the Catalyst Gardens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64843] = { id = 64843, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Key Crafting", description = "With those agitated automa quelled, there is but one task ahead.\n\nWe shall ferry you and your Enlightened companion up to the Creation Catalyst.\n\nThe rest is up to you.", progress = "It is incredible to see the Creation Catalyst up close.", completion = "We have done it!", objectives = "Restore the Translocator Key at the Creation Catalyst.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64844] = { id = 64844, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Pilgrimage Ends", description = "You have rescued many pilgrims, and I have restored your entrance to the Sepulcher. With that, our bargain is concluded--and so, too, is my pilgrimage.\n\nBut your journey continues.\n\nReturn to the overlook behind Pilgrim's Grace and open the translocator.\n\nMy thanks, {name}. This adventure has been... enlightening.", progress = "Let us listen to what they have to say.", completion = "The next step is a large one. Are you ready, {name}?", objectives = "Return to the overlook behind Pilgrim's Grace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64846] = { id = 64846, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Torghast", description = "Countless souls are tortured in the halls of Torghast. They need your help!", completion = "Too many have been lost to Torghast. The way in is difficult... but not impossible.", objectives = "Speak with Tal-Inara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64849] = { id = 64849, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tower of the Damned", description = "We know little of Torghast. However, Fatescribe Roh-Tahl claims there is work that must be done there.\n\nHe believes there is a path for you to reach this place... and that someone there requires your aid.\n\nDo what you must to reach Torghast and aid anyone who is within.", completion = "Stay back! \n\nWait... you're not one of the Jailer's forces.\n\nBox! We have a visitor, play the nice music would you?", objectives = "Travel to Torghast by jumping into the Ring of Transference, then find any entity there that needs your aid.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64850] = { id = 64850, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Traversing Torghast", description = "I've heard of you, the Maw Walker! You must know of me, the legendary Ve'nish.\n\nI am here to find great treasures within Torghast with the aid of my box. I can see you admiring it.\n\nPerhaps we can work together. Why don't you go into Torghast ahead of me to scout ahead?\n\nI shall even reward you for anything you discover within.", progress = "How goes exploring the darkness of Torghast?", completion = "Ah, the place is filled to the brink with all sorts of terrible creatures... and also plenty of powers!\n\nPerfect! Did you hear that, box? We'll find plenty in this place... perhaps even more than that coward Ve'nari out in the Maw.\n\nAhem, thank you, Maw Walker. You've done your part well. I shall have more questions later.", objectives = "Aid Ve'nish's exploration of Torghast by completing a wing within Torghast. Use the wayfinder within Torghast to access different wings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64852] = { id = 64852, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aeon Matrix", description = "<Firim could make use of this item>", completion = "This is just what I needed! Take this in appreciation for your efforts!", objectives = "Deliver the item to Firim.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64853] = { id = 64853, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Two Paths to Tread", description = "Did that answer your question?\n\nOh, you wanted a way to completely resist Domination magic? That I'm afraid I do not know. The First Ones' language will only delay the inevitable.\n\nWhat I can tell you is that if you want to find more deliciously complex phrases of the First Ones' language, you should go to the Endless Sands and search the vaults.\n\nI wish I could go myself, but it has been overrun by those nasty Mawsworn.\n\nGood luck with the rest of your studies!", completion = "This Elder has given us an important answer to this puzzle. But now we must act on the information. Though, doing so will be difficult.\n\nFirst we must infuse the helm with those indecipherable phrases from the First Ones that are in the Endless Sands.\n\nBut that will not be enough on its own. We will need more. Let me prepare, while you acquire what we need. I will send word for you after.", objectives = "Report to the Primus in the Geometric Cavern.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64854] = { id = 64854, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trappings of Success", description = "The wildlife of Zereth Mortis are attracted to the frenetic creation energy that flows throughout the land. When the wildlife finds something charged with that energy... they eat it!\n\nThe Mawsworn Cryptoseers have become aware of this and are attempting to find such wildlife to extract any remnants of that energy.\n\nEliminate the Cryptoseers, and use the Containment Trap to subdue and examine the wildlife for our research.", progress = "You have collected data before the Cryptoseers?", completion = "This information will help us continue to unravel the mysteries of Zereth Mortis.", objectives = "Slay 5 Mawsworn Cryptoseers and examine the wildlife listed.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64860] = { id = 64860, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aetheric Lattice", description = "<Firim could make use of this item>", completion = "This is just what I needed! Take this in appreciation for your efforts!", objectives = "Deliver the item to Firim.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64861] = { id = 64861, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kismetric Disc", description = "<Firim could make use of this item>", completion = "This is just what I needed! Take this in appreciation for your efforts!", objectives = "Deliver the item to Firim.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64863] = { id = 64863, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arcane Guardians", description = "Those constructs patrolling the creche are not animated by the Earth-Warder's magic.\n\n<Dervishian narrows her eyes.>\n\nWe cannot allow there to be enemies in our midst.\n\nDestroy them to clear our path forward.", progress = "Who would dare defy the Earth-Warder in this way?", completion = "Those constructs were animated with blue dragonflight magic. \n\nThe Earth-Warder would never have allowed this!", objectives = "Defeat 4 Guardians or Constructs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[64864] = { id = 64864, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Awaken, Dracthyr", description = "<Only flashes of memory remain as you shake off what feels like an endless sleep.\n\nThe dracthyr before you is unresponsive, frozen in place by some unknown magic. You sense that within you lies the power to break your ally free.\n\nThere may be others within the creche who are suspended in this stasis.\n\nIt is your duty to awaken them.>", completion = "<Azurathel listens to your report.>\n\nMy memories are as broken as yours, {name}. But we cannot dwell on that now.\n\nWe need to assess and make a plan.", objectives = "Awaken the other dracthyr.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
